  ui_story_5046_50460101_108_option_content = "เกิดไฟไหม้ในสถานเลี้ยงเด็กกำพร้าเก่าหรือไม่?",
  ui_story_5046_50460101_109_dialog_content = "มันถูกจุดไฟโดยไม่ตั้งใจเมื่อหลายปีก่อน ทำให้อาคารไหม้วอดทั้งหลัง โชคดีที่ไม่มีเด็กได้รับบาดเจ็บ",
  ui_story_5046_50460101_110_dialog_content = "โชคดีที่ Shadowlord ผู้ใจดีได้เปิดบ้านหลังหนึ่งของเขาและปล่อยให้เด็กยากจนอาศัยอยู่ที่นั่น",
  ui_story_5046_50460101_111_dialog_content = "และพวกเขาอยู่ที่นั่นตลอดหลายปีที่ผ่านมา",
  ui_story_5046_50460101_112_dialog_content = "แต่นั่นไม่ใช่วิธีแก้ปัญหาระยะยาว ไม่ต้องพูดถึงเด็กจรจัดจำนวนมากที่ยังคงเร่ร่อนอยู่ตามท้องถนน",
  ui_story_5046_50460101_113_dialog_content = "ฉันทำเงินได้จากการซื้อขายของเก่าในช่วงไม่กี่ปีที่ผ่านมา ดังนั้นฉันจึงหวังว่าจะสร้างสถานเลี้ยงเด็กกำพร้าขึ้นใหม่และให้บ้านแก่พวกเขา",
  ui_story_5046_50460101_114_dialog_content = "แม้จะสูญเสียพ่อแม่ไป แต่พวกเขายังสามารถเติบโตได้ท่ามกลางเพื่อนฝูงและผู้คนที่มีจิตใจดี",
  ui_story_5046_50460101_115_dialog_content = "คุณน่าชื่นชมมาก คุณฮาเมล",
  ui_story_5046_50460101_116_dialog_content = "นั่นเป็นสิ่งที่สูงส่งอย่างเหลือเชื่อสำหรับคุณ คุณฮาเมลล์",
  ui_story_5046_50460101_117_dialog_content = "ฉันแค่พยายามทำสิ่งเล็กน้อยที่ทำได้เพื่อเด็กๆ",
  ui_story_5046_50460101_118_dialog_content = "หวังว่าสิ่งอำนวยความสะดวกใหม่จะยังคงปลอดภัย",
  ui_story_5046_50460101_119_dialog_content = "คำถามอื่นๆ?",
  ui_story_5046_50460101_120_option_content = "ไม่มีอะไรอีกแล้ว.",
  ui_story_5046_50460101_121_dialog_content = "มันสายไปแล้วครับท่าน เราต้องเริ่มทำรอบของเรา",
  ui_story_5046_50460101_122_dialog_content = "ขอโทษที่ห้ามคุณออกจากงาน!",
  ui_story_5046_50460101_123_dialog_content = "คุณไม่เป็นไร. การดูแลความปลอดภัยของผู้เข้าพักเป็นส่วนหนึ่งของหน้าที่ของเรา",
  ui_story_5046_50460101_124_dialog_content = "<color=#e8d9bb>ปึก—</color>",
  ui_story_5046_50460101_125_dialog_content = "หืม? คุณซีนาส คุณทำของตกหล่น",
  ui_story_5046_50460101_126_dialog_content = "(เป็นจี้ที่บอบบางและมีม้าโพนี่น่ารักอยู่ด้วย)",
  ui_story_5046_50460101_127_dialog_content = "เอานี่ไป",
  ui_story_5046_50460101_128_dialog_content = "ขอบคุณครับ",
  ui_story_5046_50460101_129_dialog_content = "มันสายไปแล้วที่รัก เราควรเริ่มรอบของเรา",
