  ui_story_5046_50460101_131_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5046_50460101_132_dialog_content = "เกิดอะไรขึ้น?!",
  ui_story_5046_50460101_133_dialog_content = "ไฟ! ไฟ!",
  ui_story_5046_50460101_134_dialog_content = "ไฟเพิ่งออกมาจากที่ไหนเลยได้อย่างไร?",
  ui_story_5046_50460101_135_dialog_content = "เป็นฝีมือของ Dark Slayer ถ้าคุณถามฉัน!",
  ui_story_5046_50460101_136_dialog_content = "Dark Slayer ป่าเถื่อนนั่นอยู่ที่นี่?!",
  ui_story_5046_50460101_137_dialog_content = "อย่าตื่นตกใจ. ดูเหมือนว่าไฟจะเริ่มต้นที่สถานเลี้ยงเด็กกำพร้า",
