  ui_story_5046_50460101_140_dialog_content = "<color=#e8d9bb>ใกล้เคียง</color>",
  ui_story_5046_50460101_141_dialog_content = "...",
  ui_story_5046_50460201_1_dialog_content = "PlayerName, คุณฮาเมล.",
  ui_story_5046_50460201_2_dialog_content = "กรุณาอยู่เฉยๆ ยาม Lumopolis จะมาถึงในไม่ช้าเพื่อปกป้องคุณ",
  ui_story_5046_50460201_3_dialog_content = "ฉันอยากไปกับคุณ! ฉันสามารถระบุคนได้ด้วยพลังจิตของฉัน!",
