  ui_story_5046_50460201_5_dialog_content = "เอาล่ะ. มันเป็นเรื่องด่วน ดังนั้นโปรดติดตามฉันอย่างใกล้ชิด ฉันจะทำให้ดีที่สุดเพื่อให้แน่ใจว่าคุณปลอดภัย!",
  ui_story_5046_50460201_6_dialog_content = "*ไอ* ที่นี่ควันเยอะมาก มองไม่เห็นอะไรเลย เราต้องดับไฟเดี๋ยวนี้...",
  ui_story_5046_50460201_7_dialog_content = "กระแสเรเดียล!",
  ui_story_5046_50460201_8_dialog_content = "เดี๋ยวก่อน คริสเตน!",
  ui_story_5046_50460201_9_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5046_50460201_10_dialog_content = "เข้ามา!",
  ui_story_5046_50460201_11_dialog_content = "ไม่นะ! นายสบายดีไหม?",
  ui_story_5046_50460201_12_dialog_content = "*ไอ*... ฉันสบายดี",
  ui_story_5046_50460201_13_dialog_content = "ไฟกำลังลามไปตามน้ำมันที่พื้น ของเหลวไวไฟนี้จะลอยอยู่เหนือน้ำและเผาไหม้ต่อไป ดังนั้นคุณจึงไม่สามารถดับด้วยน้ำได้",
  ui_story_5046_50460201_14_dialog_content = "ขอโทษนะนายที่ทำให้นายเจ็บอีกแล้ว...",
  ui_story_5046_50460201_15_dialog_content = "ตอนนี้ไม่ใช่เวลาที่จะพูดถึงเรื่องนั้น",
  ui_story_5046_50460201_16_dialog_content = "PlayerNameโปรดใช้ความสามารถทางจิตของคุณเพื่อสแกนหาผู้รอดชีวิตหรือแม้แต่สัญญาณของ Dark Slayer!",
  ui_story_5046_50460201_17_dialog_content = "ได้เลย!",
  ui_story_5046_50460201_18_option_content = "บูสต์พลัง!",
  ui_story_5046_50460201_19_dialog_content = "*สะอื้น* ช่วยด้วย...",
  ui_story_5046_50460201_20_dialog_content = "มีเด็กติดอยู่ทางนี้!",
  ui_story_5046_50460201_21_dialog_content = "...",
  ui_story_5046_50460201_22_dialog_content = "แม่คะ...",
  ui_story_5046_50460201_23_dialog_content = "*ไอ* เจ็บคอ...",
  ui_story_5046_50460201_24_dialog_content = "เธอทนไม่ได้อีกต่อไป เราต้องช่วยเธอ!",
  ui_story_5046_50460201_25_dialog_content = "มีควันมากเกินไป PlayerName. ฉันไม่เห็นคุณ!",
  ui_story_5046_50460201_26_dialog_content = "อย่าเข้าไปในนั้น! เพลิงโหมหนัก อันตรายเกินไป!",
  ui_story_5046_50460201_27_dialog_content = "ไม่ต้องกังวล ฉันมาที่นี่เพื่อช่วยคุณออกไป!",
  ui_story_5046_50460201_28_dialog_content = "ไอ ไอ... กูอยู่นี่!",
  ui_story_5046_50460201_29_dialog_content = "<color=#e8d9bb>ครืน!</color>",
  ui_story_5046_50460201_30_dialog_content = "ไม่นะ บ้านเริ่มจะพังเพราะไฟไหม้",
  ui_story_5046_50460201_31_dialog_content = "ฉันต้องหาทางออก แต่ควันหนาทึบทำให้เป็นไปไม่ได้!",
  ui_story_5046_50460201_32_dialog_content = "ฉันกลัว... *สะอื้น*",
  ui_story_5046_50460201_33_dialog_content = "ไม่เป็นไร เราจะหาทางออก!",
  ui_story_5046_50460201_34_dialog_content = "<color=#e8d9bb>บดขยี้!</color>",
  ui_story_5046_50460201_35_dialog_content = "ห้องกำลังจะถล่ม—!",
  ui_story_5046_50460201_36_dialog_content = "อ๊ากกก—!",
  ui_story_5046_50460201_37_dialog_content = "เปิดตาของคุณ คุณยังไม่ตาย",
  ui_story_5046_50460201_38_dialog_content = "คุณเป็นใครน่ะ?",
  ui_story_5046_50460201_39_dialog_content = "ในเมื่อคุณยังมีชีวิตอยู่ จงลุกขึ้นและไปซะ",
  ui_story_5046_50460201_40_dialog_content = "ด็อกกี้! *กระเซ็นและไอ*",
  ui_story_5046_50460201_41_dialog_content = "สุนัขตัวใหญ่ช่วยเราไว้!",
  ui_story_5046_50460201_42_dialog_content = "ข-บิ๊กตู่...?",
  ui_story_5046_50460201_43_dialog_content = "ฉันคิดว่าเป็นผู้หญิง... ทั้งๆ ที่เธอเป็นผู้ชาย",
  ui_story_5046_50460201_44_dialog_content = "ด็อกกี้! ไอ ไอ... ไอ้หมา! เจ้าตูบขนปุกปุยสุดน่ารัก!",
  ui_story_5046_50460201_45_dialog_content = "แบบ... ไอ ไอ... แบบช่วยชีวิตคนในสตอรี่...",
  ui_story_5046_50460201_46_dialog_content = "เงียบๆ ใจดี... ไอ ไอ... หมาตัวใหญ่!",
  ui_story_5046_50460201_47_dialog_content = "คุณจะเห่าต่อไปอีกนานแค่ไหน? ฉันจะไปถ้าคุณอยากโดนเผาจนเกรียม",
  ui_story_5046_50460201_48_dialog_content = "H-ทำไมไฟถึงไม่เผาคุณล่ะ?",
  ui_story_5046_50460201_49_dialog_content = "เปลวไฟเหล่านี้? พวกเขาไม่สามารถทำร้ายฉันได้",
  ui_story_5046_50460201_50_dialog_content = "ว-เดี๋ยวก่อน! ฉันเคยเห็นคุณที่ไหนมาก่อน...",
  ui_story_5046_50460201_51_dialog_content = "ย-คุณ คุณคือ Dark Slayer!",
  ui_story_5046_50460201_52_dialog_content = "ดาร์คสเลเยอร์? คุณจับผิดคนแล้ว",
  ui_story_5046_50460201_53_dialog_content = "ฉันชื่อฮาติ",
  ui_story_5046_50460201_54_dialog_content = "โอ้ และในเมื่อนายดูกลัวฉันมาก ปล่อยมือฉันดีไหม?",
  ui_story_5046_50460201_55_dialog_content = "คุณอยู่ที่ไหน, PlayerName?",
  ui_story_5046_50460201_56_dialog_content = "*ไอ* ฉันช่วยแล้วไฟก็ดับเกือบหมดแล้ว!",
  ui_story_5046_50460201_57_dialog_content = "ฉันคิดว่ามีคนอยู่ด้วย PlayerName!",
  ui_story_5046_50460201_58_dialog_content = "ดูเหมือนว่า...ผู้สังหารความมืด!",
  ui_story_5046_50460201_59_dialog_content = "นักฆ่าแห่งความมืด?!",
  ui_story_5046_50460201_60_dialog_content = "ผู้ต้องสงสัยลอบวางเพลิง Dark Slayer ฉันสั่งให้ปล่อยตัวประกันทันที!",
  ui_story_5046_50460201_61_dialog_content = "อย่างที่ฉันพูด ฉันไม่ใช่ Dark Slayer ฉันชื่อฮาติ",
  ui_story_5046_50460201_62_dialog_content = "และคุณหมายถึงอะไรโดยตัวประกัน?",
  ui_story_5046_50460201_63_dialog_content = "เราเปิดรับทุกเงื่อนไขตราบเท่าที่คุณอนุญาต PlayerName ไป!",
  ui_story_5046_50460201_64_dialog_content = "ข้อกำหนด? เช่นเดียวกับการแลกเปลี่ยนสิ่งหนึ่งเพื่ออีกสิ่งหนึ่ง?",
  ui_story_5046_50460201_65_dialog_content = "ฉันคิดว่า PlayerName มีค่าสำหรับคุณ คุณหรือไม่ PlayerName?",
  ui_story_5046_50460201_66_dialog_content = "ย-ใช่ ฉันเอง ฉันจะเป็นตัวประกันของคุณ ปล่อยผู้หญิงคนนั้นไป",
  ui_story_5046_50460201_67_dialog_content = "อย่าทำอะไรโง่ๆ Dark Slayer!",
  ui_story_5046_50460201_68_dialog_content = "อีกครั้งกับที่? เคืองแค่ไหน!",
  ui_story_5046_50460201_69_dialog_content = "เจ้าหมาตัวใหญ่ใจร้าย...",
  ui_story_5046_50460201_70_dialog_content = "ฮึ-!",
  ui_story_5046_50460201_71_dialog_content = "Dark Slayer มี PlayerName!",
  ui_story_5046_50460201_72_dialog_content = "เข้ามาใกล้กว่านี้แล้วฉันจะฆ่าเขา",
  ui_story_5046_50460201_73_dialog_content = "เนื่องจากเจ้าตัวนี้ดูสำคัญกับคุณมาก ฉันขอเก็บมันไว้สักพัก",
  ui_story_5046_50460201_74_dialog_content = "เฮ้ คุณจะพาฉันไปไหน ปล่อยฉัน!",
  ui_story_5046_50460201_75_dialog_content = "ช่วยด้วย!",
  ui_story_5046_50460201_76_dialog_content = "หยุดพวกเขา ยาม!",
  ui_story_5046_50460201_77_dialog_content = "อย่าปล่อยให้ Dark Slayer ลอยนวล PlayerName!",
  ui_story_5046_50460202_1_dialog_content = "ผู้คุมได้สูญเสีย Dark Slayer",
  ui_story_5046_50460202_2_dialog_content = "ขอโทษครับท่าน...",
  ui_story_5046_50460202_3_dialog_content = "มันไม่ใช่ความผิดของคุณ Dark Slayer สามารถควบคุมไฟได้ ซึ่งทำให้เธอได้เปรียบ",
  ui_story_5046_50460202_4_dialog_content = "นอกจากนี้เธอยังเคลื่อนไหวได้เร็วกว่าคนทั่วไปมาก",
