  ui_story_5046_50460202_6_dialog_content = "แผนฉุกเฉินของคุณมีประโยชน์",
  ui_story_5046_50460202_7_dialog_content = "มันยังคงวุ่นวาย แต่อย่างน้อยแขกก็ถูกอพยพออกมาอย่างปลอดภัย",
  ui_story_5046_50460202_8_dialog_content = "แต่คุณช่วยอธิบายให้ฉันฟังได้ไหมว่า PlayerName ถูก Dark Slayer จับเป็นตัวประกัน?",
