  ui_story_5046_50460202_12_dialog_content = "เอาล่ะ ทำได้ดีมาก",
  ui_story_5046_50460202_13_dialog_content = "\"Hati เพศหญิง อายุ 18 ปี ไม่ทราบสถานที่เกิด\"",
  ui_story_5046_50460202_14_dialog_content = "\"มีเวลาพักสั้นๆ ในสถานเลี้ยงเด็กกำพร้า Umbraton Shadowlord พาเธอเข้าไปหลังจากที่เธอทำให้เกิดไฟไหม้ที่สถานเลี้ยงเด็กกำพร้า\"",
  ui_story_5046_50460202_15_dialog_content = "(พ่อ...?เป็นความคิดของพ่อ?)",
  ui_story_5046_50460202_16_dialog_content = "เกิดไฟไหม้สถานเลี้ยงเด็กกำพร้า? ฟังดูเหมือนผู้กระทำผิดซ้ำ",
  ui_story_5046_50460202_17_dialog_content = "\"Hati อายุครบ 18 ปีเมื่อสองเดือนก่อน และออกจากที่ดินหลังการประเมินสำเร็จ\"",
  ui_story_5046_50460202_18_dialog_content = "(เป็นการดีกว่าที่จะแจ้งให้พ่อทราบเกี่ยวกับเรื่องนี้)",
  ui_story_5046_50460202_19_dialog_content = "นักวางเพลิงที่รู้จักแบบนั้นจะถูกปล่อยตัวไปได้อย่างไร...?",
