  ui_story_5046_50460401_69_dialog_content = "(บางทีฉันอาจจะแอบออกไปเมื่อพวกเขาไม่ได้มอง หา Bethel และบอกให้เธอรู้ว่า...)",
  ui_story_5046_50460401_70_dialog_content = "เราแค่ต้องหาวิธีทำข้อตกลงกับชายสวมหน้ากาก",
  ui_story_5046_50460401_71_dialog_content = "มีโปสเตอร์ที่ต้องการตัวคุณทั่วเมือง ฮาติ หากแสดงตัวจะถูกจับกุมก่อนขึ้นสู่โต๊ะเจรจา",
