  ui_story_5046_50460402_55_dialog_content = "แม้ว่าพวกเขาทุกคนจะกระจัดกระจายไปหลังจากไฟไหม้ แทบเป็นไปไม่ได้เลยที่จะหาคนคุยด้วย",
