  ui_story_5046_50460402_57_dialog_content = "\"คุณฮาเมลบริจาคเงินให้กับสถานเลี้ยงเด็กกำพร้ามาเป็นเวลานาน และจัดกิจกรรมการกุศลเป็นประจำเพื่อระดมทุนสำหรับสถานนี้...\"",
  ui_story_5046_50460402_58_dialog_content = "คุณฮาเมล?!",
  ui_story_5046_50460402_59_dialog_content = "<color=#e8d9bb>ภายในสถานเลี้ยงเด็กกำพร้า</color>",
  ui_story_5046_50460402_60_dialog_content = "ฉันขอเวลาคุณสักครู่ได้ไหม คุณฮาเมล",
  ui_story_5046_50460402_61_dialog_content = "นางสาวคริสเตน! คุณพบคาเลสไทต์แล้วใช่ไหม? ช่างวิเศษเหลือเกิน!",
  ui_story_5046_50460402_62_dialog_content = "โชคไม่ดีที่ยังไม่มีวี่แววของ Caelestite แต่ฉันมีคำถามเกี่ยวกับ Dark Slayer ที่อยากถามคุณ",
  ui_story_5046_50460402_63_dialog_content = "นักวางเพลิงคนนั้น?",
  ui_story_5046_50460402_64_dialog_content = "ฮาติเป็นผู้ต้องสงสัยรายสำคัญในคดีนี้ และเธออาจจุดไฟเพื่อแก้แค้นคนงานในสถานเลี้ยงเด็กกำพร้าเก่าที่เธอแค้นใจ",
  ui_story_5046_50460402_65_dialog_content = "คุณได้ให้ทุนและดำเนินการการกุศลสำหรับสิ่งอำนวยความสะดวกมาเป็นเวลานาน ดังนั้นคุณควรรู้สถานการณ์ดี",
  ui_story_5046_50460402_66_dialog_content = "เลยอยากถามความคิดเห็นครับ",
  ui_story_5046_50460402_67_dialog_content = "จริงอยู่ว่าฉันให้ทุนและทำงานการกุศลเพื่อสถานเลี้ยงเด็กกำพร้า",
  ui_story_5046_50460402_68_dialog_content = "แต่ผู้กำกับและบุคลากรจัดการเรื่องเฉพาะจริงๆ ฉันแค่ต้องแสดงใบหน้าของฉันในงาน",
  ui_story_5046_50460402_69_dialog_content = "สถานเลี้ยงเด็กกำพร้าจะแสดงงบการเงินให้ฉันเป็นประจำ แต่นอกเหนือจากนั้น ฉันไม่รู้อะไรอีก",
  ui_story_5046_50460402_70_dialog_content = "แต่คุณเป็นผู้อำนวยการสถานเลี้ยงเด็กกำพร้าแห่งใหม่และมีความใกล้ชิดกับสถานที่เก่า",
  ui_story_5046_50460402_71_dialog_content = "ดังนั้นหากผู้ต้องสงสัยมุ่งเป้าไปที่เจ้าหน้าที่สถานเลี้ยงเด็กกำพร้าเพื่อแก้แค้นจริงๆ คุณก็ตกเป็นเป้าหมายรายต่อไปได้",
  ui_story_5046_50460402_72_dialog_content = "ฉันหวังว่าคุณจะจำรายละเอียดเพิ่มเติมได้ นั่นจะช่วยให้เราจับกุมผู้ต้องสงสัยได้",
  ui_story_5046_50460402_73_dialog_content = "นอกจากนี้ ฉันหวังว่าคุณจะสามารถพำนักชั่วคราวในสถานที่ที่ได้รับการคุ้มครองโดย Lumo Guard",
  ui_story_5046_50460402_74_dialog_content = "ผู้ต้องสงสัยสามารถจู่โจมและขู่เอาชีวิตคุณได้ทุกเมื่อ และ Lumo Guard ก็สามารถปกป้องคุณให้ปลอดภัยได้",
  ui_story_5046_50460402_75_dialog_content = "คุณคริสเตน ทุกสิ่งที่คุณพูดเป็นการคาดเดา",
  ui_story_5046_50460402_76_dialog_content = "คุณควรรู้ สถานเลี้ยงเด็กกำพร้าเคยใหญ่ที่สุดในอัมบราตัน มีคนจำนวนมากเกินไปที่เชื่อมโยงกับมัน",
  ui_story_5046_50460402_77_dialog_content = "คุณสามารถถามใครก็ได้ที่นี่และพวกเขาอาจมีบางอย่างที่เกี่ยวข้องกับสถานที่นี้",
  ui_story_5046_50460402_78_dialog_content = "คนงานก่อสร้าง พนักงานทำความสะอาด แม้แต่คนขายของข้างถนนนอกสถานเลี้ยงเด็กกำพร้า...",
