  ui_story_5046_50460501_63_dialog_content = "ฉันต้องการเป็นผู้พิพากษาที่นำความยุติธรรมมาสู่ Lumopolis และคนที่พึ่งพาได้เช่นเดียวกับคุณ",
  ui_story_5046_50460501_64_dialog_content = "ฉันรู้ว่าหนทางยังอีกยาวไกล แต่ฉันจะไม่ไปไหนถ้าไม่เริ่มก้าวแรก",
  ui_story_5046_50460501_65_dialog_content = "แม้จะเป็นเพียงก้าวเล็กๆ ฉันก็ยังต้องก้าวต่อไป",
  ui_story_5046_50460501_66_dialog_content = "ดังนั้น โปรดให้ฉันรับรองความปลอดภัยของมิสเตอร์ฮาเมล!",
  ui_story_5046_50460501_67_dialog_content = "หึหึ...",
  ui_story_5046_50460501_68_dialog_content = "ที่รักของผม...",
  ui_story_5046_50460501_69_dialog_content = "ฉันหมายถึงคริสเตน",
  ui_story_5046_50460501_70_dialog_content = "นั่นเป็นความรู้สึกที่น่าประทับใจ และฉันรู้สึกประทับใจอย่างมากกับความมุ่งมั่น",
  ui_story_5046_50460501_71_dialog_content = "(เดี๋ยวนะ ทำไมเขาถึงโน้มตัวเข้ามาใกล้...?)",
  ui_story_5046_50460501_72_dialog_content = "(ฉันรู้สึกได้ถึงลมหายใจของเขา...)",
  ui_story_5046_50460501_73_dialog_content = "(ผมของเขากำลังทำให้ใบหน้าของฉันคัน...)",
  ui_story_5046_50460501_74_dialog_content = "และฉันก็สัมผัสได้ถึงความรักที่คุณมีต่อฉัน...",
  ui_story_5046_50460501_75_dialog_content = "(ความรัก? เขากำลังพูดถึงอะไร?)",
  ui_story_5046_50460501_76_dialog_content = "(ไม่ อย่าบอกนะ!)",
