  ui_story_5046_50460501_81_dialog_content = "ฮะฮะ...",
  ui_story_5046_50460501_82_dialog_content = "ฉันเชื่อว่าด้วยความเฉลียวฉลาดและความกล้าหาญของคุณ คุณจะพบกับความท้าทายด้วยสีที่บินได้",
  ui_story_5046_50460501_83_dialog_content = "ขอบคุณค่ะ",
  ui_story_5046_50460501_84_dialog_content = "ฉันจะไม่ทำให้คุณผิดหวังและทำภารกิจให้สำเร็จ!",
  ui_story_5046_50460501_85_dialog_content = "<color=#e8d9bb>Umbraton ชนบท</color>",
  ui_story_5046_50460501_86_dialog_content = "นั่นคือต้นเมเปิลที่สูงที่สุดในป่า",
  ui_story_5046_50460501_87_dialog_content = "ตอนนี้เราอยู่ที่นั่นแล้วหรือยัง?",
