  ui_story_5046_50460501_91_dialog_content = "เจ็บจังเลย!",
  ui_story_5046_50460501_92_dialog_content = "นั่งลง.",
  ui_story_5046_50460501_93_dialog_content = "มันไม่ร้ายแรง คุณจะสบายดี",
  ui_story_5046_50460501_94_dialog_content = "นั่งลงเถอะคุณ",
  ui_story_5046_50460501_95_dialog_content = "(น่ากลัวจัง...สู้ไม่ได้เลย...)",
  ui_story_5046_50460501_96_dialog_content = "เอาล่ะ ฉันจะนั่งพักสักครู่",
  ui_story_5046_50460501_97_dialog_content = "พับขากางเกงขึ้น.",
  ui_story_5046_50460501_98_dialog_content = "เพื่ออะไร?",
  ui_story_5046_50460501_99_dialog_content = "ฉันจะทำให้มันเจ็บน้อยลง",
  ui_story_5046_50460501_100_dialog_content = "มันไม่เจ็บขนาดนั้นหรอก... โธ่ คุณไม่ต้องม้วนผม ผมทำเองได้!",
  ui_story_5046_50460501_101_dialog_content = "ฉัน-เท่านี้ดีพอหรือยัง?",
  ui_story_5046_50460501_102_dialog_content = "ใช่ ควรจะอยู่ที่นี่ มันเจ็บเมื่อฉันกดมัน?",
  ui_story_5046_50460501_103_dialog_content = "ไม่เป็นไร แต่มือคุณร้อน! แม้ว่าในป่าจะค่อนข้างเย็น",
  ui_story_5046_50460501_104_dialog_content = "อุณหภูมิร่างกายของฉันสูงกว่าปกติ เข้ามาใกล้ๆ ถ้าคุณรู้สึกหนาว",
  ui_story_5046_50460501_105_dialog_content = "(Hati อาจดูเหมือนไม่สามารถเข้าถึงได้ แต่หูที่นุ่มฟูของเธอจะเงยขึ้นเมื่อเธอหมอบ)",
  ui_story_5046_50460501_106_dialog_content = "(และเธอก็น่ารักจริงๆ เตือนฉันให้ระวังการเดินที่นี่และนวดข้อเท้าแพลงของฉันด้วย...)",
  ui_story_5046_50460501_107_dialog_content = "มีอะไรเหรอ",
  ui_story_5046_50460501_108_dialog_content = "ไม่มีอะไร ไม่มีอะไร!",
  ui_story_5046_50460501_109_dialog_content = "เรายังมีเวลา ทำไมเราไม่หยุดพักที่นี่?",
  ui_story_5046_50460501_110_dialog_content = "ได้สิ",
  ui_story_5046_50460501_111_dialog_content = "...",
  ui_story_5046_50460501_112_dialog_content = "...",
  ui_story_5046_50460501_113_dialog_content = "(นี่มันอึดอัด ฉันควรจะพูดอะไรซักอย่าง...)",
  ui_story_5046_50460501_114_dialog_content = "บอกฉันเกี่ยวกับแม่ของคุณได้ไหม",
  ui_story_5046_50460501_115_dialog_content = "ฉันไม่ได้หมายความว่าไม่ดีด้วยเรื่องนั้น!",
  ui_story_5046_50460501_116_dialog_content = "แม่ของฉันจากฉันไปไม่นานหลังจากที่ฉันเกิด ฉันไม่เห็นด้วยซ้ำว่าเธอหน้าตาเป็นอย่างไร...",
  ui_story_5046_50460501_117_dialog_content = "...",
  ui_story_5046_50460501_118_dialog_content = "ฉันเดาว่าคุณคงไม่อยากบอกฉัน ไม่เป็นไร",
  ui_story_5046_50460501_119_dialog_content = "...",
  ui_story_5046_50460501_120_dialog_content = "บอกตามตรง ฉันเข้าใจว่าเธอต้องการฟื้นความทรงจำเหล่านั้นมากแค่ไหน",
  ui_story_5046_50460501_121_dialog_content = "...",
  ui_story_5046_50460501_122_dialog_content = "โซรอซเป็นคนที่เลี้ยงดูฉันมาหลายปี",
  ui_story_5046_50460501_123_dialog_content = "มันไม่ใช่แค่ยักษ์ใหญ่แต่เป็นทั้งเพื่อนและอาจารย์ของฉันด้วย",
  ui_story_5046_50460501_124_dialog_content = "เราแยกจากกันไม่ได้มาหลายปีแล้ว มันจะสอนฉันเกี่ยวกับโลกภายนอกและพูดคุยเมื่อฉันเบื่อ",
  ui_story_5046_50460501_125_dialog_content = "น่าเสียดายที่ตอนนี้จำฉันไม่ได้แล้ว",
  ui_story_5046_50460501_126_dialog_content = "มันสูญเสียความทรงจำด้วย?",
  ui_story_5046_50460501_127_dialog_content = "มันสูญเสียความทรงจำทั้งหมดเพื่อช่วยชีวิตฉัน ดังนั้นฉันจึงพยายามหาทางกู้คืนมัน",
