  ui_story_5046_50460501_129_dialog_content = "และนั่นคือเราทั้งคู่กำลังทำงานอย่างหนักเพื่อดึงความทรงจำกลับคืนมา",
  ui_story_5046_50460501_130_dialog_content = "ฉันเข้าใจว่าคุณรู้สึกอย่างไร และหวังว่าคุณจะจำเหตุการณ์ที่เกิดขึ้นกับแม่ของคุณได้",
