  ui_story_5046_50460501_132_dialog_content = "โปรดแจ้งให้เราทราบหากมีอะไรให้ช่วยเกี่ยวกับความทรงจำของโซรอซ",
  ui_story_5046_50460501_133_dialog_content = "ก่อนที่คุณจะสามารถช่วยได้ คุณต้องเคลียร์สถานะผู้ต้องสงสัยเสียก่อน!",
