  ui_story_5046_50460502_65_dialog_content = "(เด็กดื้อ...)",
  ui_story_5046_50460502_66_dialog_content = "(Hati คือ... เด็กดื้อ?)",
  ui_story_5046_50460502_67_dialog_content = "(ไม่ ฮาติไม่ใช่เด็กซน!)",
  ui_story_5046_50460502_68_dialog_content = "(ใช้พลังแม่ไม่เห็นด้วยช่วยคนที่รัก...)",
  ui_story_5046_50460502_69_dialog_content = "(ไม่ได้หมายความว่าฮาติเป็นเด็กซนนะ!)",
  ui_story_5046_50460502_70_dialog_content = "(ฮาติไม่ใช่เด็กดื้อ...?)",
  ui_story_5046_50460502_71_dialog_content = "(แม่ของคุณต้องมีเหตุผลที่ไม่ได้พูดแน่ๆ ที่ใจร้ายกับฮาติ...)",
  ui_story_5046_50460502_72_dialog_content = "(และตอนเด็กคุณดูเท่มากที่ใช้ไฟปกป้องแม่ของคุณ!)",
  ui_story_5046_50460502_73_dialog_content = "(เหมือนกับฮาติสุดเท่ที่ใช้ไฟปกป้องฉัน!)",
  ui_story_5046_50460502_74_dialog_content = "(Hati เป็นเด็กที่ยอดเยี่ยมและยอดเยี่ยม!)",
  ui_story_5046_50460502_75_dialog_content = "(Hati เป็นเด็กที่น่ากลัว?)",
  ui_story_5046_50460502_76_dialog_content = "(ใช่แล้ว Hati เป็นเด็กที่ยอดเยี่ยม! ตอนนี้สงบสติอารมณ์และตื่นขึ้นอย่างช้าๆ...)",
  ui_story_5046_50460502_77_dialog_content = "...",
  ui_story_5046_50460502_78_dialog_content = "PlayerName?",
  ui_story_5046_50460502_79_dialog_content = "ฉันเอง. รู้สึกโอเคใช่มั้ย?",
  ui_story_5046_50460502_80_dialog_content = "นั่นสิ...",
  ui_story_5046_50460502_81_dialog_content = "ขอโทษที่ทำให้คุณลำบากใจ",
  ui_story_5046_50460502_82_dialog_content = "ไม่ ฉันควรจะขอโทษ",
  ui_story_5046_50460502_83_dialog_content = "ฉันแอบเข้าไปในความทรงจำของคุณโดยไม่ได้รับอนุญาต...",
  ui_story_5046_50460502_84_dialog_content = "หวังว่าคุณจะไม่โกรธฉันในเรื่องนั้น!",
  ui_story_5046_50460502_85_dialog_content = "ถ้าไม่ใช่เพราะคุณ...",
  ui_story_5046_50460502_86_dialog_content = "ฉันคงจะบ้าไปแล้ว",
  ui_story_5046_50460502_87_dialog_content = "ขอบคุณ",
  ui_story_5046_50460502_88_dialog_content = "โอเค ฉันไม่ชินกับการที่คุณทำตัวไร้มารยาทในทันที",
  ui_story_5046_50460502_89_dialog_content = "อะแฮ่ม ใกล้ถึงเวลาแล้ว เราต้องไปที่ต้นไม้นั้น",
  ui_story_5046_50460502_90_dialog_content = "ถ้ายังต้องการให้ฉันฟื้นความทรงจำให้คุณหลังจากเรื่องทั้งหมดจบลง...",
  ui_story_5046_50460502_91_dialog_content = "แค่มาหาฉันที่โคลอสซัส",
  ui_story_5046_50460502_92_dialog_content = "ได้สิ",
  ui_story_5046_50460502_93_dialog_content = "นอกจากนี้ จำไว้ว่าคุณสัญญาว่าจะอธิบายทุกอย่างและเคลียร์ตัวเอง...",
  ui_story_5046_50460502_94_dialog_content = "มิฉะนั้น คุณจะได้รับรางวัลก่อนที่จะเห็นฉันด้วยซ้ำ",
  ui_story_5046_50460502_95_dialog_content = "ผมสัญญาครับ",
  ui_story_5046_50460502_96_dialog_content = "คุณทำ?",
  ui_story_5046_50460502_97_dialog_content = "รู้จักสิครับ",
  ui_story_5046_50460601_1_dialog_content = "(กลุ่มผู้พิทักษ์ Lumopolis มาถึงสถานเลี้ยงเด็กกำพร้าเมื่อเช้านี้ แต่คุณ Hamell ไม่ได้ส่งพวกเขาไป)",
  ui_story_5046_50460601_2_dialog_content = "(และเขายังพาพวกเขาออกจาก Umbraton และเข้าไปในป่าแห่งนี้ด้วย...)",
  ui_story_5046_50460601_3_dialog_content = "(ตอนนี้ทั้ง Caelestite และ Hati อยู่ที่นี่ และทั้งสองฝ่ายก็ปะทะกัน)",
  ui_story_5046_50460601_4_dialog_content = "(ผู้คุมเหล่านี้ไม่ได้ต่อสู้แบบลูโมโปลิส แต่พวกเขาสวมเครื่องแบบลูโมการ์ด)",
  ui_story_5046_50460601_5_dialog_content = "(เกิดอะไรขึ้นที่นี่...?)",
  ui_story_5046_50460601_6_dialog_content = "(มันไร้ประโยชน์ที่จะหยุดพวกเขาตอนนี้ ดังนั้นฉันควรดูจากที่นี่ชั่วคราว)",
  ui_story_5046_50460601_7_dialog_content = "ฮึก... ฮึก... ถึงอย่างนั้นก็ฆ่านายไม่ได้",
  ui_story_5046_50460601_8_dialog_content = "นายฮาเมล? คุณกำลังพูดอะไร? แล้วมาทำอะไรที่นี่?",
  ui_story_5046_50460601_9_dialog_content = "คุณซีนาสอยู่ไหน? ข้อความส่งถึงเขาไม่ใช่หรือ",
  ui_story_5046_50460601_10_dialog_content = "แทนที่จะรอให้คุณมาฆ่าฉัน ฉันชอบการนัดหยุดงานล่วงหน้ามากกว่า",
  ui_story_5046_50460601_11_dialog_content = "คุณไม่ได้ฆ่า Andre, Fairmont และ Carlotta เหรอ?",
  ui_story_5046_50460601_12_dialog_content = "คุณรู้สึกเสียใจกับสิ่งที่เกิดขึ้นกับคุณในสถานเลี้ยงเด็กกำพร้าและต้องการแก้แค้นพวกเรา?",
  ui_story_5046_50460601_13_dialog_content = "คุณอยากจะฆ่าเราทั้งคู่ในบัดดลตอนซ้อมใช่ไหม?",
  ui_story_5046_50460601_14_dialog_content = "น่าเสียดายที่แผนนั้นล้มเหลว",
  ui_story_5046_50460601_15_dialog_content = "ฉันไม่รู้ว่าคนพวกนั้นเป็นใคร และฉันก็ผ่านการซ้อมมา",
  ui_story_5046_50460601_16_dialog_content = "เลิกเล่นโง่! คุณไม่ต้องการอะไรมากไปกว่าสำหรับฉันและ—อ๊ะ!",
  ui_story_5046_50460601_17_dialog_content = "ระวัง!",
  ui_story_5046_50460601_18_dialog_content = "(มิสเตอร์ฮาเมลล้มลง! ฮาติฆ่าเขาหรือเปล่า?)",
  ui_story_5046_50460601_19_dialog_content = "รอก่อน คุณฮาเมล!",
  ui_story_5046_50460601_20_dialog_content = "เขาตายแล้ว",
  ui_story_5046_50460601_21_dialog_content = "ฮาติ เคลป์ คุณเป็นผู้ต้องสงสัยในคดีฆาตกรรม ฉันขอให้คุณมาที่ Umbraton กับฉันเพื่อสอบสวนเพิ่มเติม!",
  ui_story_5046_50460601_22_dialog_content = "นางสาวคริสเตน? คุณมาทำอะไรที่นี่?",
  ui_story_5046_50460601_23_dialog_content = "ฉันไม่ได้ฆ่าเขา",
  ui_story_5046_50460601_24_dialog_content = "แน่นอนคุณจะพูดอย่างนั้น",
  ui_story_5046_50460601_25_dialog_content = "ฉันสามารถยืนยันความบริสุทธิ์ของ Hati นาย Hamell ไม่ถูกแตะต้อง",
  ui_story_5046_50460601_26_dialog_content = "ทำไมคุณถึงเก็บงำฆาตกร PlayerName?",
  ui_story_5046_50460601_27_dialog_content = "เธอยังคงถืออาวุธร้ายแรงอยู่ในมือ...",
  ui_story_5046_50460601_28_dialog_content = "ฉันกำลังบอกความจริง!",
  ui_story_5046_50460601_29_dialog_content = "ในเมื่อคุณต้องการปกป้องตัวเอง ทำไมคุณไม่มาที่ Hall of Justice กับฉัน",
  ui_story_5046_50460601_30_dialog_content = "แม้ว่าฉันจะเป็นเพียงผู้พิพากษาภาคทัณฑ์ แต่ฉันก็ต้องเห็นว่าความยุติธรรมนั้นได้รับใช้ และไม่มีอาชญากรรมใดที่ลอยนวลได้",
  ui_story_5046_50460601_31_dialog_content = "ไม่มีทาง ฉันยังไปกับคุณไม่ได้",
  ui_story_5046_50460601_32_dialog_content = "การต่อต้านการจับกุมรังแต่จะทำให้สิ่งต่างๆ แย่ลง",
  ui_story_5046_50460601_33_dialog_content = "ใช่อะไรก็ตาม",
  ui_story_5046_50460601_34_dialog_content = "ได้โปรดใจเย็นทั้งคู่!",
  ui_story_5046_50460601_35_dialog_content = "คริสเตน! คุณสบายดีไหม?",
  ui_story_5046_50460601_36_dialog_content = "คุณมาช้า ชายสวมหน้ากาก",
  ui_story_5046_50460601_37_dialog_content = "นี่คือคุณฮาเมล?",
  ui_story_5046_50460601_38_dialog_content = "ฮาติ? คุณฆ่าคุณฮาเมล ใช่ไหม จับกุมเธอเดี๋ยวนี้ คริสเตน",
  ui_story_5046_50460601_39_dialog_content = "รอสักครู่! ฮาติไม่ได้ทำอะไรเลย!",
  ui_story_5046_50460601_40_dialog_content = "คุณต้องการที่จะต่อสู้? ไม่มีปัญหากับฉัน!",
  ui_story_5046_50460601_41_dialog_content = "ที่นั่นอันตราย PlayerName, มานี่สิ!",
  ui_story_5046_50460601_42_dialog_content = "เอานี่ไปกินนี่ซะ!",
  ui_story_5046_50460601_43_dialog_content = "นายชักช้าเกินไปแล้วนะ",
  ui_story_5046_50460601_44_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5046_50460601_45_dialog_content = "หน้ากากของฉัน...",
  ui_story_5046_50460601_46_dialog_content = "ใบหน้า...!",
  ui_story_5046_50460601_47_dialog_content = "เขาคือใคร? เขาคือใคร?!",
  ui_story_5046_50460601_48_dialog_content = "มีอะไรเหรอ ฮาติ?",
  ui_story_5046_50460601_49_dialog_content = "ฉัน... เอ่อ... อ๊ะ...!",
  ui_story_5046_50460601_50_dialog_content = "<color=#e8d9bb>\"วันนั้น-\"</color>",
  ui_story_5046_50460601_51_dialog_content = "<color=#e8d9bb>\"ฉันเห็นใบหน้านี้\"</color>",
  ui_story_5046_50460601_52_dialog_content = "<color=#e8d9bb>\"วันนั้น-\"</color>",
  ui_story_5046_50460601_53_dialog_content = "<color=#e8d9bb>“เกิดอะไรขึ้น...กับฉัน...แม่?”</color>",
  ui_story_5046_50460601_54_dialog_content = "อ๊ากกก!",
  ui_story_5046_50460601_55_dialog_content = "ฮาติ? ฮาติ?!",
  ui_story_5046_50460601_56_dialog_content = "มีบางอย่างผิดปกติกับเธอครับท่าน",
  ui_story_5046_50460601_57_dialog_content = "อ๊าาาาา!",
  ui_story_5046_50460601_58_dialog_content = "ฮาติ! ฮาติ! คุณได้ยินฉันไหม?",
  ui_story_5046_50460601_59_dialog_content = "อย่าเหม่อสิ! ตั้งสติหน่อย!",
  ui_story_5046_50460601_60_dialog_content = "อัก!",
  ui_story_5046_50460601_61_dialog_content = "<color=#e8d9bb>เสียงดังฉ่า—</color>",
  ui_story_5046_50460601_62_dialog_content = "หน้าตาเธอเปลี่ยนไป! และเธอเป็นไฟ?!",
  ui_story_5046_50460601_63_dialog_content = "ระมัดระวัง! ถอยไป คริสเตน!",
  ui_story_5046_50460601_64_dialog_content = "อู้หู้!!!",
  ui_story_5046_50460601_65_dialog_content = "ฮาติ!!!",
  ui_story_5046_50460601_66_dialog_content = "(รูปลักษณ์ของเธอตอนนี้คล้ายกับปีศาจในตัวที่ฉันเห็นในความทรงจำของเธอ...)",
  ui_story_5046_50460601_67_dialog_content = "(มันพรากเธอไปหรือเปล่า ไม่มีทาง ฉันต้องตะครุบเธอออกมาให้ได้!)",
  ui_story_5046_50460601_68_dialog_content = "มาตรงนี้, PlayerName! Hati เป็นภัยคุกคามที่อันตรายในขณะนี้!",
  ui_story_5046_50460601_69_dialog_content = "ไม่เป็นไร ฮาติจะไม่ทำร้ายฉัน! เธอต้องการฉันเดี๋ยวนี้!",
  ui_story_5046_50460601_70_dialog_content = "คุณต้องใจเย็นๆ ฮาติ!",
  ui_story_5046_50460601_71_dialog_content = "บรู๊ววว!",
  ui_story_5046_50460601_72_dialog_content = "หยุดเสียเวลา เธอไม่ฟัง!",
  ui_story_5046_50460601_73_dialog_content = "มาทางนี้เร็ว PlayerName!",
  ui_story_5046_50460601_74_dialog_content = "PlayerName...",
  ui_story_5046_50460601_75_dialog_content = "ฮาติกำลังเรียกชื่อฉัน!",
  ui_story_5046_50460601_76_dialog_content = "ไม่ ฉันจะทิ้งเธอไว้คนเดียวไม่ได้!",
  ui_story_5046_50460601_77_dialog_content = "(มีทางใดให้เธอได้ยินฉันบ้าง...)",
  ui_story_5046_50460601_78_dialog_content = "(ฉันทำได้ ฉันทำได้...)",
  ui_story_5046_50460601_79_option_content = "บูสต์พลัง!",
  ui_story_5046_50460601_80_dialog_content = "(ใจเย็นๆ ฮาติ!)",
  ui_story_5046_50460601_81_dialog_content = "(PlayerName? ฉัน... ฉันควบคุมตัวเองไม่ได้... เมื่อเห็นหน้าผู้ชายคนนั้น...)",
  ui_story_5046_50460601_82_dialog_content = "(หัวฉันเริ่มเจ็บมากแล้ว Urgh—)",
  ui_story_5046_50460601_83_dialog_content = "(ฉันกำลังจะทำอะไร...?)",
  ui_story_5046_50460601_84_dialog_content = "(ยังไงเราก็ต้องออกไปจากที่นี่แล้วหาที่สงบๆ ให้เธอพักผ่อน)",
  ui_story_5046_50460601_85_dialog_content = "(เราไปด้วยกัน...?)",
  ui_story_5046_50460601_86_dialog_content = "(ด้วยกัน!)",
  ui_story_5046_50460601_87_dialog_content = "อย่าปล่อยให้พวกมันหนีไปได้! ฮึ",
  ui_story_5046_50460601_88_dialog_content = "หยุดก่อน นายบาดเจ็บ!",
  ui_story_5046_50460601_89_dialog_content = "Caelestite อยู่ที่ไหน",
  ui_story_5046_50460601_90_dialog_content = "ฮาติพาเขาไปด้วย...",
  ui_story_5046_50460601_91_dialog_content = "หนู เธอหนีไปอีกแล้ว!",
  ui_story_5046_50460601_92_dialog_content = "หน้ากากของฉันอยู่ที่ไหน",
  ui_story_5046_50460601_93_dialog_content = "ฉันจะหามาให้คุณ อยู่เฉยๆ!",
  ui_story_5046_50460601_94_dialog_content = "(แผลบนใบหน้า...)",
  ui_story_5046_50460601_95_dialog_content = "ไม่นะ ไฟไหม้!",
  ui_story_5046_50460601_96_dialog_content = "คุณหนูยังอยู่ข้างใน!",
  ui_story_5046_50460601_97_dialog_content = "ยังมีใครอยู่ในนั้นไหม?",
  ui_story_5046_50460601_98_dialog_content = "ได้โปรดเถอะ ฉันขอให้คุณช่วยมิสคริสเตน!",
  ui_story_5046_50460601_99_dialog_content = "แค่ก แค่ก...",
  ui_story_5046_50460601_100_dialog_content = "แม่...พ่อ...หนูอยู่ไหน...",
  ui_story_5046_50460601_101_dialog_content = "พี่สาว...",
  ui_story_5046_50460601_102_dialog_content = "ใคร...นี่คือใคร...",
  ui_story_5046_50460601_103_dialog_content = "ในที่สุดก็พบคุณ. ไม่ต้องกลัว ฉันจะกำจัดคุณออกจากสิ่งนี้",
  ui_story_5046_50460601_104_dialog_content = "คุณสบายดีไหม ผู้หญิงของฉัน",
  ui_story_5046_50460601_105_dialog_content = "ฉันสบายดี ขอบคุณ—อ๊ะ!",
  ui_story_5046_50460601_106_dialog_content = "ไม่นะ! ใบหน้าของคุณได้รับบาดเจ็บสาหัส! ต้องรักษาด่วน!",
  ui_story_5046_50460601_107_dialog_content = "ฉัน? ฉันขอโทษที่ทำให้หญิงสาวตกใจกลัว",
  ui_story_5046_50460601_108_dialog_content = "ฉันขอโทษ คุณช่วยฉันไว้เพียงเพื่อ...",
  ui_story_5046_50460601_109_dialog_content = "ใช้ได้. ฉันดีใจที่คุณไม่เป็นไร",
  ui_story_5046_50460601_110_dialog_content = "ฉันขอชื่อคุณได้ไหม...?",
  ui_story_5046_50460601_111_dialog_content = "เซนัส.",
  ui_story_5046_50460601_112_dialog_content = "ตั้งแต่วันนี้เป็นต้นไป ฉันเป็นครูสอนพิเศษที่บ้านของคุณ คุณผู้หญิง",
  ui_story_5046_50460601_113_dialog_content = "เยี่ยมมากท่าน!",
  ui_story_5046_50460601_114_dialog_content = "ฉันขอบคุณที่คุณยอมรับผู้สูงศักดิ์ต่ำต้อยอย่างฉัน และแนะนำฉันให้รู้จักกับพ่อของคุณ",
  ui_story_5046_50460601_115_dialog_content = "คุณเป็นขุนนางใช่ไหม",
  ui_story_5046_50460601_116_dialog_content = "ใช่. ดูสิ นี่คือตราประจำตระกูลของฉัน",
  ui_story_5046_50460601_117_dialog_content = "ลายไม่ซ้ำใคร.",
  ui_story_5046_50460601_118_dialog_content = "บ้านได้ลดลงและไม่คุ้มค่าที่จะกล่าวถึงอีกต่อไป",
  ui_story_5046_50460601_119_dialog_content = "<color=#e8d9bb>“ตั้งแต่นั้นมาท่านก็อยู่สอนข้าพเจ้า”</color>",
  ui_story_5046_50460601_120_dialog_content = "<color=#e8d9bb>\"จนกว่าเขาจะลาออกและไปรับใช้ลูโมโปลิสในฐานะทางการ\"</color>",
  ui_story_5046_50460601_121_dialog_content = "<color=#e8d9bb>\"หลังจากที่ฉันเรียนจบจาก Dawn Academy ฉันก็เข้าร่วม Lumo Hall of Justice และติดตามเขาต่อไป\"</color>",
  ui_story_5046_50460601_122_dialog_content = "หน้ากากของคุณครับ",
  ui_story_5046_50460601_123_dialog_content = "เฮ้อ...",
  ui_story_5046_50460601_124_dialog_content = "ฮาติฆ่ามิสเตอร์ฮาเมลและลักพาตัวคาเลสไทต์ไปอีกครั้ง",
  ui_story_5046_50460601_125_dialog_content = "เราต้องส่งผู้คุมไปติดตามและขยายการสืบสวนของเรา",
  ui_story_5046_50460601_126_dialog_content = "ครับ!",
  ui_story_5046_50460601_127_dialog_content = "นี่คือจุดที่คุณออกจากคดีนี้ คริสเตน",
  ui_story_5046_50460601_128_dialog_content = "ว่าไง",
  ui_story_5046_50460601_129_dialog_content = "เมื่อพิจารณาว่าคดีจะยิ่งแย่ลง ฉันไม่อยากให้คุณตกอยู่ในอันตรายไปมากกว่านี้",
  ui_story_5046_50460601_130_dialog_content = "นอกจากนี้ จากเหตุการณ์ที่เกิดขึ้นกับ Hamell ฉันคิดว่าคุณยังขาดประสบการณ์ที่จะเข้าไปพัวพันกับผู้ต้องสงสัย",
  ui_story_5046_50460601_131_dialog_content = "แต่ไม่มีใครลงทุนในคดีนี้มากไปกว่าฉัน ยกเว้นคุณ โปรดให้ฉันช่วยเหลือคุณต่อไป!",
  ui_story_5046_50460601_132_dialog_content = "อย่าพูดอีก. ฉันจะจัดการพวกมันเอง",
  ui_story_5046_50460601_133_dialog_content = "เพียงรวบรวมสิ่งที่ค้นพบทั้งหมดไว้ในไฟล์เดียวแล้วส่งไปยัง Hall of Justice",
  ui_story_5046_50460601_134_dialog_content = "แต่—",
  ui_story_5046_50460601_135_dialog_content = "เพียงพอ! คุณอาจเป็นหญิงสาวของฉัน แต่ฉันเป็นหัวหน้าของคุณ",
  ui_story_5046_50460601_136_dialog_content = "โปรดทำตามคำสั่งของฉัน!",
  ui_story_5046_50460601_137_dialog_content = "ใช่แล้ว...",
  ui_story_5046_50460601_138_dialog_content = "ฉันอาจจะรุนแรงเกินไปกับคำพูดของฉัน แต่ก็เป็นห่วงความปลอดภัยของคุณ",
  ui_story_5046_50460601_139_dialog_content = "คุณควรกลับไปเดี๋ยวนี้",
  ui_story_5046_50460601_140_dialog_content = "ครั้งแรกที่ฉันส่งไปติดตามผู้ต้องสงสัยและฉันก็ยุ่งไปหมด",
  ui_story_5046_50460601_141_dialog_content = "แม้ว่าเขาจะไม่อนุญาต ฉันก็จะจัดการเรื่องนี้ให้ถึงที่สุด",
  ui_story_5046_50460601_142_dialog_content = "ไม่ต้องพูดถึงฉันมีข้อสงสัยเกี่ยวกับกรณีเหล่านี้ทั้งหมด ...",
  ui_story_5046_50460601_143_dialog_content = "ถ้าฮาติตั้งใจจะจุดไฟ ทำไมเธอถึงช่วย PlayerName และสาวน้อย?",
  ui_story_5046_50460601_144_dialog_content = "นอกจากนี้ทำไมจะ PlayerName พูดเพื่อ Hati และช่วยเธอหลบหนีเมื่อเขาเป็นตัวประกัน?",
  ui_story_5046_50460601_145_dialog_content = "ก่อนที่เขาจะเสียชีวิต Hamell กล่าวว่า Hati มีเป้าหมายอื่นอยู่ข้างๆเขา",
  ui_story_5046_50460601_146_dialog_content = "ค้นหาว่าใครเป็นใคร แล้วฉันจะหาฮาติให้เจอ",
  ui_story_5046_50460601_147_dialog_content = "คุณซีนาส ครั้งนี้ฉันจะพิสูจน์ให้คุณเห็นว่าฉันไม่ใช่ดอกไม้ที่ถูกตามใจอีกต่อไป!",
  ui_story_5046_50460601_148_dialog_content = "ฉันจะเป็นผู้ช่วยเหลือที่ประเมินค่ามิได้ด้วยความสามารถของฉันเอง!",
  ui_story_5046_50460701_1_dialog_content = "(ฮึผ้าห่มเปียกแย่ที่สุด)",
  ui_story_5046_50460701_2_dialog_content = "(หลังคารั่วอีกแล้วเหรอ บ้านเก่าไม่เคยเป็นแบบนี้เลย)",
  ui_story_5046_50460701_3_dialog_content = "แม่...แม่?",
  ui_story_5046_50460701_4_dialog_content = "(แม่หลับหรือยัง)",
  ui_story_5046_50460701_5_dialog_content = "(ช่วงนี้เธอออกไปข้างนอกบ่อย และต้องทำอาหารและทำงานบ้านเมื่อกลับถึงบ้าน ดังนั้นเธอคงจะเหนื่อยมาก)",
  ui_story_5046_50460701_6_dialog_content = "(ตอนนี้ฉันโตเป็นสาวแล้วและไม่สามารถสร้างปัญหาให้แม่ได้!)",
  ui_story_5046_50460701_7_dialog_content = "(ฉันต้องตากผ้าห่มเอง!)",
  ui_story_5046_50460701_8_dialog_content = "(เธอจะมีความสุขมากเมื่อเห็นฉันทำงานบ้านหลังจากตื่นนอน!)",
  ui_story_5046_50460701_9_dialog_content = "(เธอจะเรียกฉันว่าเด็กดี!)",
  ui_story_5046_50460701_10_dialog_content = "<color=#e8d9bb>พั่บ พั่บ... พั่บ พั่บ...</color>",
  ui_story_5046_50460701_11_dialog_content = "(ว้าววว น่าทำจัง ปกติแม่จะห่มผ้าไว้กี่ผืนเนี่ย)",
  ui_story_5046_50460701_12_dialog_content = "(ถ้ามันแห้งก่อนที่แม่จะตื่น!)",
  ui_story_5046_50460701_13_dialog_content = "แห้งเปล่า!",
  ui_story_5046_50460701_14_dialog_content = "แบล็กกี้ แบล็กกี้!",
  ui_story_5046_50460701_15_dialog_content = "แห้งทันที!",
  ui_story_5046_50460701_16_dialog_content = "<color=#e8d9bb>เสียงดังฉ่า—</color>",
  ui_story_5046_50460701_17_dialog_content = "โว่ว!",
  ui_story_5046_50460701_18_dialog_content = "ไฟมาจากไหน!",
  ui_story_5046_50460701_19_dialog_content = "แม่จะบ้าตายถ้าแม่เห็นแบบนี้!",
  ui_story_5046_50460701_20_dialog_content = "ฉันต้องดับไฟ!",
  ui_story_5046_50460701_21_dialog_content = "ฮาติ? คุณกำลังทำอะไร?!",
  ui_story_5046_50460701_22_dialog_content = "บู้ฮู้...แม่!",
  ui_story_5046_50460701_23_dialog_content = "(เธอดูหวาดกลัวมาก... ฉันต้องขอโทษแล้ว!)",
  ui_story_5046_50460701_24_dialog_content = "ขอโทษ ฉันแค่ต้องการตากผ้าห่ม...",
  ui_story_5046_50460701_25_dialog_content = "ฉันไม่ได้ตั้งใจจะจุดไฟ...มันแค่...",
  ui_story_5046_50460701_26_dialog_content = "เจ้าบาดเจ็บรึเปล่า",
  ui_story_5046_50460701_27_dialog_content = "ไม่... ผมไม่ได้ตั้งใจ แม่...",
  ui_story_5046_50460701_28_dialog_content = "และฉันไม่ได้ตั้งใจจะทำอะไรที่คุณไม่ต้องการให้ฉันทำ...",
  ui_story_5046_50460701_29_dialog_content = "เอาล่ะ จำไว้ว่าอย่าใช้พลังของคุณอีก!",
  ui_story_5046_50460701_30_dialog_content = "คุณได้ยินฉันไหม!?",
  ui_story_5046_50460701_31_dialog_content = "(แม่ดุมาก...)",
  ui_story_5046_50460701_32_dialog_content = "แต่ฉันก็แค่... ไม่ได้ตั้งใจ...",
  ui_story_5046_50460701_33_dialog_content = "วะฮะฮะ—!",
  ui_story_5046_50460701_34_dialog_content = "ตอนนี้ยังควบคุมพลังไม่ได้...",
  ui_story_5046_50460701_35_dialog_content = "และแรงมากพอที่จะทำร้ายคุณได้หากคุณประมาท...",
  ui_story_5046_50460701_36_dialog_content = "ยังมีคนที่ต้องการพลังและอาจทำให้คุณเจ็บปวดได้เช่นกัน...",
  ui_story_5046_50460701_37_dialog_content = "ดังนั้นอย่าใช้มันอีกเลย คุณได้ยินไหม Hati?",
  ui_story_5046_50460701_38_dialog_content = "บู้ฮู้... เข้าใจแล้ว...",
  ui_story_5046_50460701_39_dialog_content = "(แม่...)",
  ui_story_5046_50460701_40_dialog_content = "<color=#e8d9bb>“กลัวพลังฉันขนาดนั้นเลยเหรอแม่”</color>",
  ui_story_5046_50460701_41_dialog_content = "<color=#e8d9bb>“แม่กลัวหนูขนาดนั้นเลยเหรอ”</color>",
  ui_story_5046_50460701_42_dialog_content = "<color=#e8d9bb>“แต่ผมรักคุณที่สุดครับแม่!”</color>",
  ui_story_5046_50460701_43_dialog_content = "อ๊ากกก!",
  ui_story_5046_50460701_44_dialog_content = "(แม่ไม่ต้องการฮาติแล้ว...)",
  ui_story_5046_50460701_45_dialog_content = "(เพราะฮาติไม่ฟังเธอ...)",
  ui_story_5046_50460701_46_dialog_content = "ฉัน... อึก... แม่... อึก!",
  ui_story_5046_50460701_47_dialog_content = "ตื่นได้แล้ว ฮาติ!",
  ui_story_5046_50460701_48_dialog_content = "(เธอดูเหมือนจะติดอยู่ในความทรงจำของเธอ)",
  ui_story_5046_50460701_49_dialog_content = "(ฉันสัมผัสได้ถึงปีศาจในตัวเธอที่กระซิบข้างหูเธออย่างไม่ลดละ...)",
  ui_story_5046_50460701_50_dialog_content = "หากฮาติไม่สามารถเผชิญหน้ากับปีศาจร้ายในตัวเธอได้ เธอก็จะติดอยู่ในความทรงจำของเธอตลอดไป...",
  ui_story_5046_50460701_51_dialog_content = "การปล่อยให้เธอล่องลอยไปในอดีตโดยไม่รู้ตัวเช่นนี้ไม่ใช่ทางเลือก",
  ui_story_5046_50460701_52_dialog_content = "ฉันต้องช่วยเธอให้ได้!",
  ui_story_5046_50460701_53_option_content = "บูสต์พลัง!",
  ui_story_5046_50460701_54_dialog_content = "(ที่นี่ต้องเป็นบ้านของ Hati)",
  ui_story_5046_50460701_55_dialog_content = "ฮาติ! คุณกำลังทำอะไร!?",
  ui_story_5046_50460701_56_dialog_content = "M-แม่?",
  ui_story_5046_50460701_57_dialog_content = "ตอบฉันสิ—คุณกำลังทำอะไร!?",
  ui_story_5046_50460701_58_dialog_content = "ฉันแค่อยากจะดูว่าเด็กๆข้างนอกกำลังเล่นอะไรกัน",
  ui_story_5046_50460701_59_dialog_content = "ปิดหน้าต่าง! ตอนนี้!",
  ui_story_5046_50460701_60_dialog_content = "แต่ฉันก็อยากออกไปเล่นด้วย",
  ui_story_5046_50460701_61_dialog_content = "ฉันบอกคุณกี่ครั้งแล้ว คุณต้องการให้ฉันทำซ้ำหรือไม่",
  ui_story_5046_50460701_62_dialog_content = "ร้องไห้...",
  ui_story_5046_50460701_63_dialog_content = "ทำไมไม่ปล่อยให้ออกไปเล่น!?",
  ui_story_5046_50460701_64_dialog_content = "คุณมักจะพูดว่ามันเป็นการป้องกันตัวของฉันเอง!",
  ui_story_5046_50460701_65_dialog_content = "แต่คุณไม่เคยบอกฉันว่าทำไมเป็น!",
  ui_story_5046_50460701_66_dialog_content = "...",
  ui_story_5046_50460701_67_dialog_content = "สถานที่ใหม่ที่เราย้ายไปนี้ทรุดโทรมและหนาวเย็นมาก! ที่นี่น่ากลัว!",
  ui_story_5046_50460701_68_dialog_content = "คุณไม่มีหนังสือภาพเหล่านั้นหรือ ไปหาอ่านเอาเอง",
  ui_story_5046_50460701_69_dialog_content = "แต่ฉันอ่านหนังสือเหล่านั้นมาหลายครั้งแล้ว!",
  ui_story_5046_50460701_70_dialog_content = "เด็กๆ ในหนังสือเหล่านั้นสามารถเล่นด้วยกันและเยี่ยมเยียนกันได้...",
  ui_story_5046_50460701_71_dialog_content = "คุณใช้หนังสือภาพเหล่านั้นสอนฉันถึงวิธีพูดคุยกับผู้คน ซื้อของ และกล่าวขอบคุณ...",
  ui_story_5046_50460701_72_dialog_content = "...",
  ui_story_5046_50460701_73_dialog_content = "แต่ฉันไม่มีโอกาสได้ใช้มันเลย!",
  ui_story_5046_50460701_74_dialog_content = "เพราะนายไม่ให้ฉันออกไป!",
  ui_story_5046_50460701_75_dialog_content = "ฉันสอนสิ่งเหล่านี้ให้คุณเพราะ...",
  ui_story_5046_50460701_76_dialog_content = "ฉันหวังว่าคุณจะดูแลตัวเองได้สักวันหนึ่ง เมื่อฉันไม่อยู่แล้ว",
