  ui_story_5046_50460701_81_dialog_content = "ฉันโตแล้ว!",
  ui_story_5046_50460701_82_dialog_content = "ถ้ามีใครมารังแก ฉันจะตีให้หมดจนกว่าพวกมันจะหนีไป!",
