  ui_story_5046_50460701_84_dialog_content = "!!!",
  ui_story_5046_50460701_85_dialog_content = "<color=#e8d9bb>ผัวะ!</color>",
  ui_story_5046_50460701_86_dialog_content = "ม...แม่?",
  ui_story_5046_50460701_87_dialog_content = "บอกแล้วใช่ไหมว่าทำไม่ได้!?",
  ui_story_5046_50460701_88_dialog_content = "แม่...คุณตีฉัน...",
