  ui_story_5046_50460701_104_dialog_content = "...จี้...บน...",
  ui_story_5046_50460701_105_dialog_content = "(ความทรงจำส่วนนี้ของเธอคลุมเครือมาก...)",
  ui_story_5046_50460701_106_dialog_content = "แม่คุณกำลังทำอะไร คุณดูเครียด",
  ui_story_5046_50460701_107_dialog_content = "วันนี้เป็นวันเกิดของฉัน! อยากกินเค้กสตรอเบอรี่!",
  ui_story_5046_50460701_108_dialog_content = "...ฮาติ...ฟังฉันนะ",
  ui_story_5046_50460701_109_dialog_content = "มันสายเกินไป... มันสายเกินไปสำหรับการพูดคุยเช่นนี้ ไม่มีเวลา",
  ui_story_5046_50460701_110_dialog_content = "ใช้จี้นี้ เก็บไว้ใกล้ ๆ และอย่าทำหาย!",
  ui_story_5046_50460701_111_dialog_content = "แม่ว่าไงนะ? ฉันไม่เข้าใจ.",
  ui_story_5046_50460701_112_dialog_content = "คนไม่ดี... คนไม่ดีกำลังมาหาคุณ",
  ui_story_5046_50460701_113_dialog_content = "คนไม่ดี? WHO?",
  ui_story_5046_50460701_114_dialog_content = "แม่จ๋า คนเลวคนนี้คือใคร?",
  ui_story_5046_50460701_115_dialog_content = "แม่คุณจะทำอะไร แม่?",
  ui_story_5046_50460701_116_dialog_content = "หวา—!",
  ui_story_5046_50460701_117_dialog_content = "<color=#e8d9bb>“แม่ครับ คนเลวคนนี้คือใคร”</color>",
  ui_story_5046_50460701_118_dialog_content = "<color=#e8d9bb>\"ทำไมคนเลวถึงมาทำกับเราแบบนี้...\"</color>",
  ui_story_5046_50460701_119_dialog_content = "<color=#e8d9bb>“แม่ว่า...หนูเป็นคนไม่ดีเหรอ”</color>",
  ui_story_5046_50460701_120_dialog_content = "<color=#e8d9bb>“เธอจุดไฟเผาฉันงั้นเหรอ...”</color>",
  ui_story_5046_50460701_121_dialog_content = "<color=#e8d9bb>“ผมใช่ไหมครับแม่”</color>",
  ui_story_5046_50460701_122_dialog_content = "(ในที่สุดก็เข้าใจ...ฮาติ...)",
  ui_story_5046_50460701_123_dialog_content = "(คนไม่ดีที่แม่พูดถึง...คือเธอ...)",
  ui_story_5046_50460701_124_dialog_content = "(ฉันเกลียดพลังนี้... พลังนี้... มันกลืนกินพวกเราไปทั้งตัว...)",
  ui_story_5046_50460701_125_dialog_content = "เรา...?",
  ui_story_5046_50460701_126_dialog_content = "ฮาติ! ฮาติ!",
  ui_story_5046_50460701_127_dialog_content = "นั่นใครน่ะ...?",
  ui_story_5046_50460701_128_dialog_content = "ฉันเอง! PlayerName!",
  ui_story_5046_50460701_129_dialog_content = "PlayerName? คุณอยากจะ... ทิ้งฉันด้วยเหรอ?",
  ui_story_5046_50460701_130_dialog_content = "(PlayerName...ที่รักของคุณ PlayerName...)",
  ui_story_5046_50460701_131_dialog_content = "(เขาจะทิ้งคุณไว้ข้างหลังด้วย...)",
  ui_story_5046_50460701_132_dialog_content = "(ใครชอบคนที่จุดไฟให้ทุกอย่าง...? คนที่ควบคุมไฟของตัวเองไม่ได้...)",
  ui_story_5046_50460701_133_dialog_content = "(คนที่ทำให้แม่โกรธเสมอ...จนแม่ทิ้งไปในที่สุด...ฮาติ...)",
  ui_story_5046_50460701_134_dialog_content = "แม่ไม่รัก...จะไม่มีใคร...",
  ui_story_5046_50460701_135_dialog_content = "มันไม่ใช่อย่างนั้นนะครับ!",
  ui_story_5046_50460701_136_dialog_content = "ทุกครั้งที่คุณใช้พลังของคุณ ก็เพื่อคนสำคัญของคุณ!",
  ui_story_5046_50460701_137_dialog_content = "เพื่อป้องกันไม่ให้ Eclipsites ทำร้ายแม่ของคุณ... ตากผ้านวมเอง เพื่อให้แม่ของคุณได้พักผ่อนมากขึ้น...",
  ui_story_5046_50460701_138_dialog_content = "ช่วยฉันจากกลุ่ม Eclipsites เมื่อฉันหมดหนทางที่จะต่อสู้กับพวกเขา...",
  ui_story_5046_50460701_139_dialog_content = "การใช้พลังต้องห้ามของคุณเพื่อประโยชน์ของคนที่คุณรัก...",
  ui_story_5046_50460701_140_dialog_content = "ไม่เห็นเหรอฮาติ? คุณเป็นผู้หญิงที่ใจดีและมีน้ำใจมาก!",
  ui_story_5046_50460701_141_dialog_content = "นั่นคือสิ่งที่ฉันชอบเกี่ยวกับคุณ!",
  ui_story_5046_50460701_142_dialog_content = "และฉันรู้ว่าแม่ของคุณก็ต้องรู้สึกแบบเดียวกัน!",
  ui_story_5046_50460701_143_dialog_content = "มารดาของท่านจะไม่รักบุตรธิดาอย่างเมตตาและเห็นอกเห็นใจท่านได้อย่างไร?",
  ui_story_5046_50460701_144_dialog_content = "แม่...รักหนูไหม?",
  ui_story_5046_50460701_145_dialog_content = "(เขาโกหกคุณ...)",
  ui_story_5046_50460701_146_dialog_content = "ทุกสิ่งที่ฉันพูดเป็นความจริง!",
  ui_story_5046_50460701_147_dialog_content = "คุณเป็นคนโกหก! สิ่งที่คุณทำคือทำลาย Hati ลง! คุณเป็นคนไม่ดี!",
  ui_story_5046_50460701_148_dialog_content = "ฮาติ มาเอาชนะคนเลวคนนี้ด้วยกันเถอะ!",
  ui_story_5046_50460702_1_dialog_content = "ฉันชนะ?",
  ui_story_5046_50460702_2_dialog_content = "(คุณชนะไหม...?)",
  ui_story_5046_50460702_3_dialog_content = "(ไม่... คุณยังอยู่ที่นี่... ฉันยังอยู่ที่นี่...)",
  ui_story_5046_50460702_4_dialog_content = "(คุณยังไม่สามารถ...ยอมรับตัวเองได้อย่างแท้จริง...)",
  ui_story_5046_50460702_5_dialog_content = "คุณคืออะไร?",
  ui_story_5046_50460702_6_dialog_content = "(พวกเราจะเจอกันใหม่...)",
  ui_story_5046_50460702_7_dialog_content = "ฮาติ!",
  ui_story_5046_50460702_8_dialog_content = "อึก...อึก...",
  ui_story_5046_50460702_9_dialog_content = "อืม? PlayerName...?",
  ui_story_5046_50460702_10_dialog_content = "สุดยอด ในที่สุดคุณก็ตื่น",
  ui_story_5046_50460702_11_dialog_content = "...",
  ui_story_5046_50460702_12_dialog_content = "ขอบคุณ คุณเพิ่งช่วยฉันอีกครั้ง",
  ui_story_5046_50460702_13_dialog_content = "คุณไม่จำเป็นต้องขอบคุณฉัน คุณช่วยฉันจาก Eclipsites เมื่อกี้นี้!",
  ui_story_5046_50460702_14_dialog_content = "...",
  ui_story_5046_50460702_15_dialog_content = "ฉันอยากได้จี้ของฉันคืนจากชายสวมหน้ากากคนนั้นเพราะมันเป็นของแม่ฉัน",
  ui_story_5046_50460702_16_dialog_content = "ตั้งแต่ฉันยังเป็นเด็ก ฉันมักจะแตกต่างจากคนอื่นๆ ฉันทำได้เพียงดูพวกเขาจากระยะไกลผ่านหน้าต่าง และไม่ได้รับอนุญาตให้ออกไปข้างนอก",
  ui_story_5046_50460702_17_dialog_content = "ในโลกของฉันมีเพียงแม่เท่านั้น",
  ui_story_5046_50460702_18_dialog_content = "เธอเล่นเกมกับฉัน สอนฉันอ่านหนังสือ อ่านนิทานให้ฉันฟัง... แม่คือทุกสิ่งสำหรับฉัน",
  ui_story_5046_50460702_19_dialog_content = "ฉันรักเธอมาก แต่แม่ของฉัน... บางทีเธออาจจะไม่ได้รักฉันเท่าที่ฉันรักเธอ",
  ui_story_5046_50460702_20_dialog_content = "พูดแบบนั้นได้ยังไง...?",
  ui_story_5046_50460702_21_dialog_content = "เท่าที่ฉันจำความได้ เรามักจะเคลื่อนไหวอยู่เสมอ และไม่เคยอยู่ที่ใดที่หนึ่งนานเกินไป",
  ui_story_5046_50460702_22_dialog_content = "แม่ของฉันมักจะมองฉันด้วยสายตาที่แฝงไปด้วยความกลัว และเธอไม่เคยปล่อยให้ฉันออกไปไหนเลย",
  ui_story_5046_50460702_23_dialog_content = "บ้านหลังสุดท้ายของเราคือบ้านที่เราอยู่นานที่สุด มันยังเป็นจุดจบของวัยเด็กของฉันอีกด้วย...",
  ui_story_5046_50460702_24_dialog_content = "ฮาติ...",
  ui_story_5046_50460702_25_dialog_content = "ฉันมักจะพยายามหนี เพื่อหลีกเลี่ยงไม่ให้นึกถึงวันนั้น แต่ฉันจะลืมได้อย่างไร",
  ui_story_5046_50460702_26_dialog_content = "26 สิงหาคม วันนั้น...เป็นวันเกิดของฉัน",
  ui_story_5046_50460702_27_dialog_content = "?!",
  ui_story_5046_50460702_28_dialog_content = "ฮาติ...",
  ui_story_5046_50460702_29_dialog_content = "แม้ว่าแม่ของฉันอาจจะเข้มงวดในบางครั้ง แต่เธอก็ดีกับฉันจริงๆ",
  ui_story_5046_50460702_30_dialog_content = "เธอจำวันเกิดของฉันได้เสมอและเตรียมทุกอย่างล่วงหน้าหนึ่งวัน เธอทำเค้กสตอเบอรี่ครีมกับฉันด้วย...",
  ui_story_5046_50460702_31_dialog_content = "วันนั้นแม่ตื่นแต่เช้าเหมือนเคยแต่ดูมีอารมณ์แปลกๆ",
  ui_story_5046_50460702_32_dialog_content = "เธอแค่อวยพรวันเกิดให้ฉันแล้วเริ่มยุ่งอยู่กับบ้านเหมือนกำลังเตรียมอะไรบางอย่าง",
  ui_story_5046_50460702_33_dialog_content = "ฉันถามไปเรื่อยว่ากินเค้กได้ไหม แต่แม่ไม่ตอบ",
  ui_story_5046_50460702_34_dialog_content = "จากนั้นเธอก็โยนฉันเข้าไปในเตาไฟ เธอพยายามจะเผาฉันทั้งเป็น",
  ui_story_5046_50460702_35_dialog_content = "ทำไมเธอถึงทำอย่างนั้น!?",
  ui_story_5046_50460702_36_dialog_content = "ฉันจำไม่ได้จริงๆ ว่าเกิดอะไรขึ้นหลังจากที่เธอโยนฉันเข้าไปในกองไฟ เมื่อฉันตื่นขึ้นฉันอยู่ที่สถานเลี้ยงเด็กกำพร้า",
