  ui_story_5046_50460702_38_dialog_content = "ฉันอยากออกไปเล่นกับเด็กคนอื่นๆ เสมอ แต่ฉันไม่เคยคิดมาก่อนว่ามันจะเป็นแบบนี้",
  ui_story_5046_50460702_39_dialog_content = "ฉันเรียนรู้ที่จะเข้ากับเด็กคนอื่นๆ และผู้ใหญ่ในสถานเลี้ยงเด็กกำพร้า แต่พวกเขาไม่ค่อยเป็นมิตร",
  ui_story_5046_50460702_40_dialog_content = "เด็กๆ ทะเลาะกันอยู่เสมอ และผู้ใหญ่ก็ใจร้ายกับเรามาก",
  ui_story_5046_50460702_41_dialog_content = "ที่นั่นน่ากลัวมาก และฉันแค่อยากจะบ่นกับแม่ แต่ฉันไม่รู้ว่าแม่อยู่ที่ไหน",
  ui_story_5046_50460702_42_dialog_content = "เมื่อฉันรู้...ว่าเธอทิ้งฉันไป",
  ui_story_5046_50460702_43_dialog_content = "คืนหนึ่ง ผู้คนในสถานเลี้ยงเด็กกำพร้าพยายามทำอะไรกับฉันขณะที่ฉันหลับ ฉันพยายามดิ้นสุดกำลังแล้วก็มีใครบางคนตัดหูฉัน",
  ui_story_5046_50460702_44_dialog_content = "หูของฉันหลุดออกมาแบบนั้น ฉันไม่เคยเจ็บปวดมากขนาดนี้มาก่อน",
  ui_story_5046_50460702_45_dialog_content = "ฉันควบคุมอารมณ์ไม่ได้—ฉันระบายความโกรธและเผาสถานเลี้ยงเด็กกำพร้าทั้งหลัง",
  ui_story_5046_50460702_46_dialog_content = "อย่างที่คุณทราบ ฉันถูกส่งไปหา Shadowlord หลังจากนี้ และเขาปล่อยฉันไปเมื่อสองเดือนก่อน",
  ui_story_5046_50460702_47_dialog_content = "ฮาติ...",
  ui_story_5046_50460702_48_dialog_content = "ไม่มีแม่คนไหนไม่รักลูก",
  ui_story_5046_50460702_49_dialog_content = "ฉันแน่ใจว่าเธอต้องการให้คุณมีชีวิตที่ดีไม่ว่าคุณจะเจออะไร",
  ui_story_5046_50460702_50_dialog_content = "คุณไม่จำเป็นต้องพยายามทำให้ฉันรู้สึกดีขึ้น PlayerName.",
  ui_story_5046_50460702_51_dialog_content = "ถ้าแม่รักฉัน ทำไมแม่ต้องโยนฉันเข้าไปในเตาไฟนั่นด้วย?",
  ui_story_5046_50460702_52_dialog_content = "ฉันรู้ว่านั่นไม่ใช่สิ่งที่คุณคิดในใจลึก ๆ ใช่ไหม Hati?",
  ui_story_5046_50460702_53_dialog_content = "ไม่อย่างนั้นทำไมคุณถึงพยายามอย่างหนักเพื่อค้นหาความทรงจำที่หายไปนั้น",
  ui_story_5046_50460702_54_dialog_content = "คุณต้องเชื่อว่าแม่ของคุณยังรักคุณอยู่ที่ไหนสักแห่งในใจคุณ",
  ui_story_5046_50460702_55_dialog_content = "...",
  ui_story_5046_50460702_56_dialog_content = "...หืม..",
  ui_story_5046_50460702_57_dialog_content = "เมื่อตอนนี้ฉันสูญเสียการควบคุมตัวเอง ทำไมคุณไม่ออกไปกับคนอื่น ๆ ท่ามกลางความสับสนวุ่นวายทั้งหมด?",
  ui_story_5046_50460702_58_dialog_content = "เพราะ... ฉันคิดว่าคุณอาจต้องการความช่วยเหลือจากฉัน",
  ui_story_5046_50460702_59_dialog_content = "นอกจากกริมม์แล้ว ไม่มีใครพยายามอย่างหนักที่จะช่วยฉัน",
  ui_story_5046_50460702_60_dialog_content = "เหมาะแค่เพื่อนคอยเกื้อหนุนกัน",
  ui_story_5046_50460702_61_dialog_content = "เพื่อน? ฉันไม่มีเพื่อนเลย",
  ui_story_5046_50460702_62_dialog_content = "จากนี้ไป คุณสามารถเรียกฉันว่าเพื่อนของคุณ",
  ui_story_5046_50460702_63_dialog_content = "คุณได้ค้นหาความทรงจำของคุณตลอดสองเดือนตั้งแต่คุณออกจาก Shadowlord",
  ui_story_5046_50460702_64_dialog_content = "แต่ยังมีโลกใบใหญ่ที่รอให้คุณไปสำรวจ",
  ui_story_5046_50460702_65_dialog_content = "เมื่อเจ้าฟื้นความทรงจำแล้ว ก็มาเที่ยวกับฉันที่ Colossus สิ!",
  ui_story_5046_50460702_66_dialog_content = "เราสามารถเดินทางรอบโลกและชดเชยเวลาที่คุณไม่ได้รับอนุญาตให้ออกไปในอดีตได้!",
  ui_story_5046_50460702_67_dialog_content = "...",
  ui_story_5046_50460702_68_dialog_content = "แล้วเธอว่าไงล่ะ",
  ui_story_5046_50460702_69_dialog_content = "...",
  ui_story_5046_50460702_70_dialog_content = "ได้สิ",
  ui_story_5046_50460801_1_dialog_content = "(คำพูดสุดท้ายของ Mr. Hamell และผู้รอดชีวิตเพียงคนเดียวที่เขาพูดถึง—ทั้งหมดเกี่ยวข้องกับสถานเลี้ยงเด็กกำพร้า)",
  ui_story_5046_50460801_2_dialog_content = "(ไม่มีเบาะแสอื่น ๆ ในขณะนี้ ผู้ต้องสงสัย Hati และ PlayerName หนีไปแล้วด้วย)",
  ui_story_5046_50460801_3_dialog_content = "(เมื่อสิ่งต่าง ๆ ยังคงอยู่ ทางเลือกเดียวของฉันคือมองหาสถานเลี้ยงเด็กกำพร้าต่อไป)",
  ui_story_5046_50460801_4_dialog_content = "(แทบจะไม่มีร่องรอยของอดีตเหลืออยู่หลังการสร้างสถานเลี้ยงเด็กกำพร้าขึ้นใหม่ ตอนนี้ มีเพียงเด็กที่เหลือจากปีนั้นเท่านั้นที่ยังไม่ได้รับการตรวจสอบ)",
  ui_story_5046_50460801_5_dialog_content = "คุณเป็นผู้พิพากษา? คุณแน่ใจหรือว่าคุณได้คนที่ใช่? ฉันเป็นแค่คนรับใช้...",
  ui_story_5046_50460801_6_dialog_content = "(มีเพียงสองคนที่ฉันพบบันทึกในเอกสารสำคัญ ดูเหมือนว่าผู้หญิงคนนี้จะแก่กว่าฮาติสองปี)",
  ui_story_5046_50460801_7_dialog_content = "(หลังจากไฟไหม้ เธอถูกส่งไปอยู่กับครอบครัวอุปถัมภ์ใกล้ๆ ตอนนี้ เธอเป็นสาวใช้ของครอบครัวผู้ดีในลูโมโปลิส)",
  ui_story_5046_50460801_8_dialog_content = "ได้โปรด ไม่จำเป็นต้องประหม่า ฉันแค่อยากรู้เกี่ยวกับไฟไหม้ที่สถานเลี้ยงเด็กกำพร้าอัมบราตัน",
  ui_story_5046_50460801_9_dialog_content = "เท่าที่ฉันรู้ คุณอยู่ที่นั่นค่อนข้างนาน",
  ui_story_5046_50460801_10_dialog_content = "พวกเขาถามคำถามเหล่านี้กับฉันหลายครั้งก่อนหน้านี้... ทำไมสิ่งนี้ถึงเกิดขึ้นอีกครั้ง?",
  ui_story_5046_50460801_11_dialog_content = "คืนนั้นฉันหลับสนิท... จนกระทั่งฉันถูกปลุกด้วยเสียงกรีดร้องของเด็กคนอื่นๆ เมื่อฉันตื่นขึ้น สถานที่ทั้งหมดก็ถูกไฟลุกท่วมแล้ว",
  ui_story_5046_50460801_12_dialog_content = "เด็กสาวคนใหม่ซึ่งเป็นกึ่งมนุษย์—ร่างกายของเธอถูกไฟไหม้ เด็กบนเตียงข้างๆ ฉันบอกว่าเธอเป็นคนเริ่มเรื่องทั้งหมด",
  ui_story_5046_50460801_13_dialog_content = "ฉันตะเกียกตะกายเพื่อออกจากที่นั่น ฉันไม่สามารถสนใจสิ่งอื่นได้มากนัก",
  ui_story_5046_50460801_14_dialog_content = "(อืม... มันเหมือนกับคำพูดก่อนหน้าของเธอทุกประการ นี่คือข้อมูลที่ทราบทั้งหมด)",
  ui_story_5046_50460801_15_dialog_content = "ตอนนั้นคุณสังเกตไหมว่ากึ่งมนุษย์ที่ชื่อฮาติทะเลาะกับใครก็ตามที่สถานเลี้ยงเด็กกำพร้า?",
  ui_story_5046_50460801_16_dialog_content = "หรือเธอมีปากเสียงกับครู ผู้บริหาร หรือคนอื่น ๆ ในสถานเลี้ยงเด็กกำพร้าหรือไม่?",
  ui_story_5046_50460801_17_dialog_content = "ฉันไม่แน่ใจ ฉันไม่ได้ยินอะไรเลย",
  ui_story_5046_50460801_18_dialog_content = "แต่การแก้แค้น...? ตอนนั้นเธออายุเท่าไหร่? เธออายุยังไม่เท่าฉันด้วยซ้ำ",
  ui_story_5046_50460801_19_dialog_content = "และเธออยู่ที่สถานเลี้ยงเด็กกำพร้าได้เพียงเดือนเดียว ใครกันที่สามารถสร้างศัตรูได้ในเวลาอันสั้นเช่นนี้?",
  ui_story_5046_50460801_20_dialog_content = "ถ้าคุณคิดว่ามันอาจเป็นไปได้จริงๆ เด็กบางคนตัวใหญ่กว่าคนอื่นๆ และชอบทุ่มน้ำหนักเพื่อรังแกคนอื่นให้ทำสิ่งที่พวกเขาต้องการ",
  ui_story_5046_50460801_21_dialog_content = "เด็กสาวกึ่งมนุษย์คนนั้นตัวเล็กเกินไปที่จะต่อสู้กับเด็กตัวโตพวกนั้น...",
  ui_story_5046_50460801_22_dialog_content = "และครูที่นั่นไม่สนใจเรื่องการโต้เถียงใดๆ ระหว่างเด็ก พวกเขาไม่อดทนและไม่ใจดี...",
  ui_story_5046_50460801_23_dialog_content = "ฉันไม่คิดว่าพวกเราจะชอบพนักงานที่นั่นเหรอ?",
  ui_story_5046_50460801_24_dialog_content = "อ้อ มีอีกอย่างที่ฉันอยากถาม",
  ui_story_5046_50460801_25_dialog_content = "คุณได้ติดต่อกับเด็ก ๆ ที่ได้รับการอุปการะจากสถานเลี้ยงเด็กกำพร้าหรือไม่?",
  ui_story_5046_50460801_26_dialog_content = "อัตราการรับเลี้ยงบุตรบุญธรรมที่สถานเลี้ยงเด็กกำพร้านั้นสูงมาก แต่ไม่มีประวัติการรับบุตรบุญธรรมและไม่มีหลักฐานการกลับมาเยี่ยม...",
  ui_story_5046_50460801_27_dialog_content = "ฉันไม่ได้ติดต่อกับใครเลย",
  ui_story_5046_50460801_28_dialog_content = "เมื่อก่อนเราเคยล้อเล่นว่าเมื่อพวกเขามารับเด็กแปดหรือเก้าคนไปทุกเดือน พวกเขาถูกป้อนให้ Eclipsites",
  ui_story_5046_50460801_29_dialog_content = "มีเด็กรับอุปการะแปดหรือเก้าคนทุกเดือน...",
  ui_story_5046_50460801_30_dialog_content = "(นี่เป็นสถานการณ์ที่ไม่ปกติจริงๆ...)",
  ui_story_5046_50460801_31_dialog_content = "ขอโทษที่ทำให้คุณเสียเวลา ขอบคุณมาก.",
  ui_story_5046_50460801_32_dialog_content = "(ผู้รอดชีวิตคนต่อไปคือเด็กชายอายุไล่เลี่ยกับฮาติ)",
  ui_story_5046_50460801_33_dialog_content = "(ตามบันทึก เขาจัดการร้านเบเกอรี่กับพ่อแม่บุญธรรมหลังจากที่เขารับเลี้ยงแล้ว)",
  ui_story_5046_50460801_34_dialog_content = "คุณเป็นผู้พิพากษา? ฉันไม่ได้ทำ nuthin'!",
  ui_story_5046_50460801_35_dialog_content = "ได้โปรด ไม่จำเป็นต้องประหม่าขนาดนั้น ฉันต้องการที่จะเข้าใจว่าเกิดอะไรขึ้นเกี่ยวกับไฟไหม้ที่สถานรับเลี้ยงเด็กกำพร้าอัมบราตัน",
  ui_story_5046_50460801_36_dialog_content = "ฮะ? เรื่องทั้งหมดเกิดขึ้นนานมาแล้ว แต่คุณยังคงตรวจสอบอยู่ใช่ไหม?",
  ui_story_5046_50460801_37_dialog_content = "แต่ฉันเกรงว่าคุณจะโชคไม่ดี ฉันบอกอะไรใหม่ไม่ได้ ทุกสิ่งที่ฉันจำได้ถูกลบออกไปแล้วในคำแถลงของฉัน",
  ui_story_5046_50460801_38_dialog_content = "ถ้าเป็นไปได้ ฉันหวังว่าคุณจะไม่ทำให้ลูกค้าของฉันตกใจ",
  ui_story_5046_50460801_39_dialog_content = "เอ่อ...",
  ui_story_5046_50460801_40_dialog_content = "ถ้าคุณช่วยฉันจำสิ่งที่เกิดขึ้นได้มากกว่านี้ ฉันจะซื้อขนมปังทั้งหมดในร้านเบเกอรี่ของคุณ",
  ui_story_5046_50460801_41_dialog_content = "จริงเหรอ!",
  ui_story_5046_50460801_42_dialog_content = "ตอนนี้คุณพูดถึงมันแล้ว ฉันอาจจะจำรายละเอียดเพิ่มเติมได้บ้าง",
  ui_story_5046_50460801_43_dialog_content = "ขอบคุณสำหรับความร่วมมือ. คุณบอกว่าฮาติจุดไฟ คุณช่วยอธิบายสิ่งที่เกิดขึ้นโดยละเอียดได้ไหม",
  ui_story_5046_50460801_44_dialog_content = "คืนนั้น... ฉันเป็นคนหลับไม่สนิทมาตลอดตั้งแต่ฉันยังเด็ก ดังนั้นฉันจึงตื่นทันทีที่ได้ยินเสียงกึ่งมนุษย์ตะโกน",
  ui_story_5046_50460801_45_dialog_content = "เตียงของฉันค่อนข้างไกลจากเธอ ฉันไม่เห็นว่าเกิดอะไรขึ้น แต่เธอเริ่มโกรธหลังจากตะโกน",
  ui_story_5046_50460801_46_dialog_content = "จากนั้นเปลวไฟก็ลุกโชนไปทั่วร่างของเธอ ไฟเริ่มใหญ่ขึ้นเรื่อย ๆ และในที่สุดเด็กคนอื่น ๆ ก็ตื่นขึ้น",
  ui_story_5046_50460801_47_dialog_content = "ฉันวิ่งไปหามันพร้อมกับเด็กคนอื่นๆ แต่ขาของฉันถูกไฟไหม้ ฉันพูดทั้งหมดนี้มาก่อนเมื่อพวกเขาถามฉันในรอบแรก",
  ui_story_5046_50460801_48_dialog_content = "แล้วคุณรู้หรือไม่ว่าฮาติซึ่งเป็นกึ่งมนุษย์สร้างศัตรูในสถานเลี้ยงเด็กกำพร้า?",
  ui_story_5046_50460801_49_dialog_content = "เหยื่อของการโจมตีวางเพลิงเมื่อเร็ว ๆ นี้ล้วนเกี่ยวข้องกับสถานเลี้ยงเด็กกำพร้า อยากทราบว่าพวกเขาแค้นฮาติหรือไม่",
  ui_story_5046_50460801_50_dialog_content = "มีเด็กใหม่มาปรากฏตัวที่สถานเลี้ยงเด็กกำพร้าอยู่เสมอ แต่ส่วนใหญ่จบลงด้วยการถูกส่งออกไปก่อนที่พวกเขาจะได้รู้จักใครจริงๆ",
  ui_story_5046_50460801_51_dialog_content = "ถ้าไม่ใช่เพราะเธอเป็นกึ่งมนุษย์ ฉันคงจำไม่ได้ด้วยซ้ำว่าเธอเป็นใคร นับประสาอะไรที่เธอเข้ากับคนไม่ได้",
  ui_story_5046_50460801_52_dialog_content = "ส่วนคนที่ดูแลสถานเลี้ยงเด็กกำพร้า...",
  ui_story_5046_50460801_53_dialog_content = "พวกเขาต้องรับมือกับเด็กเหลือขอที่ส่งเสียงดังกลุ่มใหญ่ทุกวัน และไม่มีใครเป็นของตัวเอง",
  ui_story_5046_50460801_54_dialog_content = "แม้ว่าภายนอกจะดูเป็นมิตร แต่ใครจะรู้ว่าพวกเขาเป็นอย่างไรหลังประตูปิด?",
  ui_story_5046_50460801_55_dialog_content = "(ดูเหมือนว่าทุกคนจะมีความรู้สึกไม่ดีต่อเจ้าหน้าที่ของสถานเลี้ยงเด็กกำพร้า...)",
  ui_story_5046_50460801_56_dialog_content = "คุณเคยติดต่อกับเด็กคนอื่นๆ ที่รับเลี้ยงมาจากสถานเลี้ยงเด็กกำพร้าบ้างไหม?",
  ui_story_5046_50460801_57_dialog_content = "หรือคุณมีรายละเอียดการติดต่อของครอบครัวรับเลี้ยงบุตรบุญธรรมหรือไม่?",
  ui_story_5046_50460801_58_dialog_content = "ฉันขาดการติดต่อกับทุกคนหลังจากที่พวกเขารับเลี้ยงบุตรบุญธรรม",
  ui_story_5046_50460801_59_dialog_content = "สำหรับรายละเอียดการติดต่อของครอบครัวบุญธรรม...",
  ui_story_5046_50460801_60_dialog_content = "นั่นเป็นสิ่งที่ผู้กำกับควรจดบันทึกไว้ไม่ใช่หรือ",
  ui_story_5046_50460801_61_dialog_content = "คุณรู้ไหม ฉันเคยเห็นครูที่สถานเลี้ยงเด็กกำพร้าจ้องมองไปที่เด็กบางคน เขียนและวาดภาพลงในสมุดบันทึกของพวกเขา",
  ui_story_5046_50460801_62_dialog_content = "และเมื่อถึงเวลารับเลี้ยง เด็กเหล่านี้คือเด็กที่ถูกส่งตัวไป",
  ui_story_5046_50460801_63_dialog_content = "ตอนนี้ฉันคิดดูแล้ว สมุดบันทึกเหล่านั้นน่าจะมีข้อมูลมากมายเกี่ยวกับบุตรบุญธรรมใช่ไหม? ไม่รู้สิ—คุณเป็นผู้พิพากษา คุณน่าจะมีอำนาจตรวจสอบพวกเขาได้ ใช่ไหม?",
  ui_story_5046_50460801_64_dialog_content = "น่าเสียดายที่ดูเหมือนว่าทุกอย่างจะถูกทำลายในกองเพลิง",
  ui_story_5046_50460801_65_dialog_content = "ยังไงก็ขอบคุณที่ให้ความร่วมมือ ฉันจะเอาขนมปังทั้งหมดที่คุณมี",
  ui_story_5046_50460801_66_dialog_content = "(วุ้ย ฉันจัดการกับขนมปังจำนวนมหาศาลนั่นได้แล้ว แต่ตอนนี้...)",
  ui_story_5046_50460801_67_dialog_content = "(ยังมีเรื่องของบรรดาลูกบุญธรรมที่หายตัวไป และฮาติ ที่ถูกกล่าวหาว่าเป็นฆาตกรตอนที่เธอยังเด็ก)",
  ui_story_5046_50460801_68_dialog_content = "(สถานเลี้ยงเด็กกำพร้าแบบไหนกันที่ประสบความสำเร็จในการรับเด็กจำนวนมากทุกเดือน แล้วพวกเขาก็หายไปอย่างไร้ร่องรอย?)",
  ui_story_5046_50460801_69_dialog_content = "(สถานการณ์ที่เลวร้ายที่สุดคือพวกเขาใช้เพื่อบางสิ่งบางอย่าง ... )",
  ui_story_5046_50460801_70_dialog_content = "(เป็นความคิดที่น่าสยดสยอง... แต่ถ้าเป็นเรื่องจริง Hati เพิ่งจะก่อไฟและฆ่าคุณ Hamell)",
  ui_story_5046_50460801_71_dialog_content = "(ยิ่งคิดก็ยิ่งหวั่นไหว ความลับมากมายที่ซ่อนอยู่ในสถานเลี้ยงเด็กกำพร้าเก่าแห่งนั้น?)",
  ui_story_5046_50460801_72_dialog_content = "โอ๊ะ...",
  ui_story_5046_50460801_73_dialog_content = "ดูขั้นตอนของคุณพลาด",
  ui_story_5046_50460801_74_dialog_content = "ขอบคุณนะ...",
  ui_story_5046_50460801_75_dialog_content = "ชื่อกริมม์ ฉันเป็นเจ้าของ Firefly Bar อยู่ตรงหัวมุมถนน",
  ui_story_5046_50460801_76_dialog_content = "กริมม์? คุณไม่ใช่เพื่อนของ Hati เหรอ? คุณซีนาสกล่าวถึงคุณ",
  ui_story_5046_50460801_77_dialog_content = "โอ้ คุณเคยได้ยินเกี่ยวกับฉันไหม ฟังนะ จะว่าอะไรไหมถ้าเราเก็บเรื่องเล็กๆ น้อยๆ ไว้คุยทีหลัง? มีบางอย่างที่ฉันสงสัยจริงๆ ว่าคุณจะช่วยฉันได้ไหม",
