  ui_story_5046_50460801_81_dialog_content = "ฉันเพิ่งจัดการกับสิ่งโสโครกสองสามอย่างในย่านชานเมืองเสร็จ",
  ui_story_5046_50460801_82_dialog_content = "สุริยุปราคา!? ระวังข้างหลังคุณ!",
  ui_story_5046_50460802_1_dialog_content = "ขอบคุณหญิงสาว ถ้าตอนนี้คุณไม่ได้มาช่วย Eclipsites เหล่านั้นคงทำงานสั้น ๆ ให้ฉัน",
  ui_story_5046_50460802_2_dialog_content = "มันไม่มีอะไรเลย อีกอย่าง ฉันอยากถามอะไรคุณเกี่ยวกับฮาติ",
  ui_story_5046_50460802_3_dialog_content = "แน่นอน. Firefly Bar อยู่ตรงหัวมุมข้างหน้า มานั่งคุยกันจิบเครื่องดื่ม",
  ui_story_5046_50460802_4_dialog_content = "<color=#e8d9bb>ดิง—!</color>",
  ui_story_5046_50460802_5_dialog_content = "ขออภัยในความไม่สะดวก.",
  ui_story_5046_50460802_6_dialog_content = "คุณเพิ่งทำให้ฉันแข็งจริงๆ มิส นี่คือสิ่งที่ฉันทำได้น้อยที่สุด",
  ui_story_5046_50460802_7_dialog_content = "กรุณานั่ง ยังไม่ใช่เวลาทำการ คุณต้องการจะดื่มอะไรไหม?",
  ui_story_5046_50460802_8_dialog_content = "ฉันอยู่เวร ฉันไม่ดื่ม",
  ui_story_5046_50460802_9_dialog_content = "นอกจากเครื่องดื่มแอลกอฮอล์แล้ว เรายังมีเครื่องดื่มซอฟต์ดริงก์ให้เลือกมากมายที่นี่",
  ui_story_5046_50460802_10_dialog_content = "มี Blue Storm, Umbraton Delight, White Night Iced Tea...",
  ui_story_5046_50460802_11_dialog_content = "ไม่เป็นไรขอบคุณ. มาตรงประเด็นกันเถอะ",
  ui_story_5046_50460802_12_dialog_content = "คุณกับฮาติพบกันได้อย่างไร?",
  ui_story_5046_50460802_13_dialog_content = "เธอทำงานกับฉันที่นี่ใช่ไหม!",
  ui_story_5046_50460802_14_dialog_content = "เธอมักจะจัดการเรื่องวัตถุดิบ ทำความสะอาดครัว... งานหลายอย่างจริงๆ เธอไม่พูดมาก แต่เธอเป็นคนทำงานหนักคนหนึ่ง",
  ui_story_5046_50460802_15_dialog_content = "Hati อยู่ที่ไหนเมื่อเกิดไฟไหม้ครั้งล่าสุด?",
  ui_story_5046_50460802_16_dialog_content = "ตอนนี้ไม่ใช่เรื่องล่าสุดเลย ฉันจำไม่ได้อย่างถูกต้อง",
  ui_story_5046_50460802_17_dialog_content = "อย่างไรก็ตาม ฉันจำวันนี้ได้ชัดเจนมาก เป็นวันจัดซื้อ",
  ui_story_5046_50460802_18_dialog_content = "ฮาติยุ่งทั้งวันในครัว นับสต็อกและตรวจสอบความสดของวัตถุดิบ เธอไม่มีโอกาสพักผ่อนจนถึงเย็น",
  ui_story_5046_50460802_19_dialog_content = "(นี่คือวันที่ Fairmont ถูกสังหาร ตามคำให้การของ Grimme Hati ไม่มีโอกาสที่จะลงมือฆาตกรรม)",
  ui_story_5046_50460802_20_dialog_content = "(อย่างไรก็ตาม Grimme อาจพยายามปกป้อง Hati)",
  ui_story_5046_50460802_21_dialog_content = "นางโปรดเชื่อฉัน ฉันกำลังบอกความจริงกับคุณ",
  ui_story_5046_50460802_22_dialog_content = "คุณสามารถเรียกฉันว่าคริสเตน",
  ui_story_5046_50460802_23_dialog_content = "กลับไปที่ Hati—คุณมีข้อมูลอื่นเกี่ยวกับเธอที่สามารถแบ่งปันกับฉันได้ไหม",
  ui_story_5046_50460802_24_dialog_content = "เช่น เธอเคยเอ่ยถึงการอาฆาตแค้นใครบ้างไหม? เธอเคยพูดถึงการแก้แค้นหรืออะไรที่คล้ายกันบ้างไหม?",
  ui_story_5046_50460802_25_dialog_content = "อย่างที่ฉันพูด Hati ไม่พูดมาก เราไม่ได้รู้จักกันมานาน แต่ฉันไม่เคยได้ยินเธอพูดถึงอะไรแบบนั้นเลยตลอดเวลาที่ฉันรู้จักเธอ",
  ui_story_5046_50460802_26_dialog_content = "(นี่ดูเหมือนจะไม่ได้พาฉันไปไหนเลย)",
  ui_story_5046_50460802_27_dialog_content = "ในกรณีนี้ ฉันจะไม่รบกวนคุณอีกต่อไป ขอให้เป็นวันที่ดี.",
  ui_story_5046_50460802_28_dialog_content = "คุณจะออกไปโดยไม่ลองน้ำผลไม้โฮมเมดที่ฉันทำเพื่อคุณโดยเฉพาะเหรอ?",
  ui_story_5046_50460802_29_dialog_content = "คุณดูไม่สนใจเครื่องดื่มที่ฉันพูดถึงก่อนหน้านี้เลย ฉันจึงผสมเครื่องดื่มพิเศษให้คุณในตอนนี้",
  ui_story_5046_50460802_30_dialog_content = "คุณควรรู้ ฉันเป็นมิกโซโลจิสต์ที่เก่งที่สุดใน Umbraton",
  ui_story_5046_50460802_31_dialog_content = "ไม่จำเป็นหรอก",
  ui_story_5046_50460802_32_dialog_content = "อย่าเป็นอย่างนั้น เครื่องดื่มสำหรับเรื่องราวที่คร่อมความจริงและความเท็จ นั่นคือสิ่งที่ทำใน Umbraton",
  ui_story_5046_50460802_33_dialog_content = "อะไรเป็นโทษในการลองดูใช่มั้ย?",
  ui_story_5046_50460802_34_dialog_content = "(ดูเหมือนกริมม์พยายามจะบอกเป็นนัยอะไรบางอย่าง... แล้วทำไมจู่ ๆ ก็มายืนใกล้ฉันจัง!)",
  ui_story_5046_50460802_35_dialog_content = "ผมยังมีหน้าที่ราชการที่ต้องจัดการและผู้กระทำความผิดยังไม่ถูกจับ ฉันไม่สามารถ...",
  ui_story_5046_50460802_36_dialog_content = "คุณดูเศร้ามากเมื่อฉันเห็นคุณที่ถนน กรณีชนกำแพงอิฐหรือไม่?",
  ui_story_5046_50460802_37_dialog_content = "ถึงเวลาเช่นนี้เราควรนั่งดื่มและฟังนิทานเพื่อผ่อนคลาย คุณอาจพบแรงบันดาลใจใหม่ๆ",
  ui_story_5046_50460802_38_dialog_content = "(นั่นฟังดูถูกต้อง)",
  ui_story_5046_50460802_39_dialog_content = "(ไม่มีเงื่อนงำอื่นใดที่จะดำเนินการในขณะนี้ ฉันควรนั่งลงและฟัง)",
  ui_story_5046_50460802_40_dialog_content = "ดี แต่เพียงหนึ่งเดียว",
  ui_story_5046_50460802_41_dialog_content = "ฮิฮิ ถ้าอย่างนั้นฉันขอเริ่มเรื่องเลยแล้วกัน",
  ui_story_5046_50460802_42_dialog_content = "เมื่อสิบปีก่อน Umbraton ไม่มี Shadowlord และไม่มีใครสนใจการต่อสู้และการฆ่าฟันที่เกิดขึ้นตามท้องถนน นับประสากับสถานเลี้ยงเด็กกำพร้าแห่งหนึ่งในเขตชานเมือง",
  ui_story_5046_50460802_43_dialog_content = "แต่สถานเลี้ยงเด็กกำพร้าแถบชานเมืองแห่งนี้ยังคงเปิดทำการได้...",
  ui_story_5046_50460802_44_dialog_content = "คุณคิดว่าสาเหตุของสิ่งนั้นคืออะไร?",
  ui_story_5046_50460802_45_dialog_content = "ในสังคมที่ปั่นป่วนนี้ สถานเลี้ยงเด็กกำพร้ายังคงเปิดดำเนินการได้... ฉันคิดว่าเป็นเพราะการสนับสนุนจากผู้มีจิตกุศล",
  ui_story_5046_50460802_46_dialog_content = "ถูกต้อง. สถานเลี้ยงเด็กกำพร้าได้รับการสนับสนุน แต่ไม่มีองค์กรการกุศล",
  ui_story_5046_50460802_47_dialog_content = "สถานเลี้ยงเด็กกำพร้ามีพนักงานเพียงห้าคนและผู้อำนวยการหนึ่งคน และไม่มีแม้แต่ข่าวลือที่แผ่วเบาว่านายใหญ่ Umbraton คนใดที่ทำให้สถานที่นั้นยังคงอยู่",
  ui_story_5046_50460802_48_dialog_content = "และบ่อยครั้ง เด็กบางคนถูกรับเลี้ยง ขณะที่เด็กบางคนถูกส่งไปสถานเลี้ยงเด็กกำพร้า...",
  ui_story_5046_50460802_49_dialog_content = "มันเหมือนกับการซื้อและขายเครื่องดื่มหลังบาร์",
  ui_story_5046_50460802_50_dialog_content = "D-คุณหมายความว่าสถานเลี้ยงเด็กกำพร้าแห่งนี้ดำเนินการค้าเด็กหรือไม่?",
  ui_story_5046_50460802_51_dialog_content = "อย่าช้า เรื่องนี้ยังไม่จบ",
  ui_story_5046_50460802_52_dialog_content = "พวกเขากล่าวว่าบุตรบุญธรรมถูกส่งไปยังขุนนางบางคนของลูโมโปลิส—ขุนนางที่มีสายเลือดแต่สูญพันธุ์ไปแล้ว",
  ui_story_5046_50460802_53_dialog_content = "อย่างไรก็ตาม ฉันได้ยินมาว่าเมื่อไม่นานมานี้ เจ้าหน้าที่ที่ชื่อ Pittman ได้เริ่มสืบสวนขุนนางเหล่านี้อีกครั้ง",
  ui_story_5046_50460802_54_dialog_content = "<color=#FFB400>กรณี</color> พิตต์แมนกำลังสอบสวน!",
  ui_story_5046_50460802_55_dialog_content = "พนักงานห้าคนและผู้อำนวยการหนึ่งคน... ตรงกับข้อมูลที่ฉันมีเกี่ยวกับสถานเลี้ยงเด็กกำพร้าเก่าเป๊ะ!",
  ui_story_5046_50460802_56_dialog_content = "ผู้อำนวยการสถานเลี้ยงเด็กกำพร้าเก่าเสียชีวิตในกองเพลิง และพนักงาน 3 คนเสียชีวิตในเหตุไฟไหม้ที่เกิดขึ้นในช่วง 2 เดือนที่ผ่านมา...",
  ui_story_5046_50460802_57_dialog_content = "คุณฮาเมลล์มีความเกี่ยวข้องกับสถานเลี้ยงเด็กกำพร้าเก่า และบุคคลที่เขากล่าวถึง...",
  ui_story_5046_50460802_58_dialog_content = "นั่นทำให้ห้า!",
  ui_story_5046_50460802_59_dialog_content = "ประกอบกับคำให้การที่สอบสวนเด็กทั้ง 2 คนที่รอดชีวิตจากเหตุไฟไหม้ก่อนหน้านี้...",
  ui_story_5046_50460802_60_dialog_content = "สถานเลี้ยงเด็กกำพร้าในเรื่องนี้คือสถานเลี้ยงเด็กกำพร้าเก่าใช่หรือไม่?",
  ui_story_5046_50460802_61_dialog_content = "ก็... ฉันแค่เล่านิทาน ไม่มีอะไรมาก",
  ui_story_5046_50460802_62_dialog_content = "หากคุณสามารถได้รับแรงบันดาลใจจากมันบ้างก็ดีสำหรับคุณ",
  ui_story_5046_50460802_63_dialog_content = "ฉันได้เรียนรู้มากมายจากเรื่องนี้ ฉันขอขอบคุณสำหรับความช่วยเหลือของคุณ",
  ui_story_5046_50460802_64_dialog_content = "แต่ฉันสงสัยว่า... คุณไปได้ยินเรื่องนี้มาจากไหน?",
  ui_story_5046_50460802_65_dialog_content = "คดีที่คุณพิตต์แมนสืบสวนเกี่ยวข้องกับขุนนางแห่งลูโมโพลิส",
  ui_story_5046_50460802_66_dialog_content = "ใครก็ตามที่เล่าเรื่องนี้ให้คุณรู้รายละเอียดที่แม่นยำมากมาย ไม่สามารถเป็นพลเมืองธรรมดาได้",
  ui_story_5046_50460802_67_dialog_content = "คนที่เล่าเรื่องที่นี่มักไม่ทิ้งชื่อไว้ ยิ่งฉันรู้น้อยเท่าไหร่ เรื่องราวก็ยิ่งน่าสนใจมากขึ้นเท่านั้น",
  ui_story_5046_50460802_68_dialog_content = "เงารู้ความลับทั้งหมด",
  ui_story_5046_50460802_69_dialog_content = "(กริมม์ดูไม่น่าเชื่อถือแต่พูดด้วยความแม่นยำสมบูรณ์แบบ)",
  ui_story_5046_50460802_70_dialog_content = "(การพบกันบนท้องถนนวันนี้ไม่ใช่อุบัติเหตุ ฉันถูกพามาที่นี่เพื่อฟังเรื่องทั้งหมดนี้)",
  ui_story_5046_50460802_71_dialog_content = "ทุกสิ่งที่เกิดขึ้นในทวีปนั้นเชื่อมต่อกัน ผีเสื้อใน Umbraton สามารถทำให้เกิดพายุใน Lumopolis",
  ui_story_5046_50460802_72_dialog_content = "หืมม?",
  ui_story_5046_50460802_73_dialog_content = "(หน้าตาแบบนั้นกับคำพูดที่จู่ๆ เป็นยังไง?)",
  ui_story_5046_50460802_74_dialog_content = "ฮิฮิ... เอาล่ะ เอาล่ะ หมดเวลาของเรื่องราวแล้ว",
  ui_story_5046_50460802_75_dialog_content = "ดูสิ ทิวทัศน์ยามค่ำคืนนั้นน่าทึ่งมาก คุณไม่ค่อยได้เห็นท้องฟ้ายามค่ำคืนของ Umbraton ใช่ไหม?",
  ui_story_5046_50460802_76_dialog_content = "ในตอนกลางคืน พ่อค้าแม่ค้ารายย่อยจำนวนมากจะปรากฏตัวใน Umbraton โคมไฟของพวกเขาทอดยาวราวกับสายน้ำแห่งดวงดาว เป็นภาพที่น่าจดจำ",
  ui_story_5046_50460802_77_dialog_content = "ขอบคุณสำหรับเรื่องราวของคุณ เครื่องดื่มก็ดีเหมือนกัน",
  ui_story_5046_50460802_78_dialog_content = "ฮิฮิ ม็อกเทลพิเศษนี้เป็นอะไรที่ฉันไม่เคยลองมาก่อนเลยจริงๆ ฉันแค่คิดว่าจะไปหาการผสมผสานแบบนี้หลังจากเจอคุณ",
  ui_story_5046_50460802_79_dialog_content = "เครื่องดื่มนี้มีชื่อหรือไม่?",
  ui_story_5046_50460802_80_dialog_content = "ยังไม่ได้ แต่ฉันจะเรียกมันว่า—",
  ui_story_5046_50460802_81_dialog_content = "ลิลลี่ของ Lumopolis",
  ui_story_5046_50460901_1_dialog_content = "ฮาติ คุณจำได้ไหมว่าคุณเคยอาศัยอยู่ที่ไหน",
  ui_story_5046_50460901_2_dialog_content = "หากคุณต้องการรื้อฟื้นความทรงจำในอดีต ให้ไปที่สถานที่ที่คุณเคยอาศัยอยู่และดูว่าคุณสามารถจำอะไรได้บ้าง",
  ui_story_5046_50460901_3_dialog_content = "แม่และฉันย้ายบ้านหลายครั้ง ฉันจำที่อยู่เดิมไม่ได้",
  ui_story_5046_50460901_4_dialog_content = "แต่ฉันยังจำบ้านที่ฉันจุดไฟได้ มันอยู่ใกล้อัมบราตัน",
  ui_story_5046_50460901_5_dialog_content = "คุณไม่ได้เผามัน คุณมีส่วนผิดอย่างแน่นอน",
  ui_story_5046_50460901_6_dialog_content = "ไปที่นั่นและดูรอบๆ บางทีคุณอาจจะจำอะไรบางอย่างได้",
  ui_story_5046_50460901_7_dialog_content = "นี่ไง.",
  ui_story_5046_50460901_8_dialog_content = "บ้านทุกหลังที่เราผ่านไปตามทางถูกทิ้งร้าง ดูเหมือนว่าไม่มีใครอาศัยอยู่ที่นี่เป็นเวลานาน",
  ui_story_5046_50460901_9_dialog_content = "นี่เป็นบ้านเดียวที่ถูกเผาจนเหลือแค่พื้น เพียงแค่มองแวบเดียวก็เพียงพอแล้ว",
  ui_story_5046_50460901_10_option_content = "ทำไมที่นี่จึงถูกทิ้งร้าง?",
