  ui_story_5046_50460901_127_dialog_content = "<color=#e8d9bb>เอี๊ยด—</color>",
  ui_story_5046_50460901_128_dialog_content = "(ใครอยู่เนี่ย!? ใครวะเนี่ย ไม่เคยมีใครเข้าบ้านมาก่อน!)",
  ui_story_5046_50460901_129_dialog_content = "มันไม่ง่ายเลยที่จะตามหาคุณ แคทเธอรีน เคลป์ คุณคิดว่าคุณสามารถหลบหนีได้จริงหรือ?",
  ui_story_5046_50460901_130_dialog_content = "... เสนาสนะ.",
  ui_story_5046_50460901_131_dialog_content = "Tsk บ้านนี้มืดจัง ทำไมไม่มีแสงที่นี่?",
  ui_story_5046_50460901_132_dialog_content = "ผู้หญิงบ้านๆ หรูๆ แบบนี้? ดูเหมือนว่าช่วงนี้ชีวิตของคุณไม่ค่อยจะดีนัก",
  ui_story_5046_50460901_133_dialog_content = "บ้านที่ฉันอยู่จะโทรมแค่ไหน ตราบใดที่เธอตาย ฉันก็จะอยู่ดีกินดี",
  ui_story_5046_50460901_134_dialog_content = "จุ๊—ผู้หญิงที่ดีไม่เคยพูดจาหยาบคายแบบนี้",
  ui_story_5046_50460901_135_dialog_content = "เรื่องไร้สาระเพียงพอ",
  ui_story_5046_50460901_136_dialog_content = "วันนี้ข้าต้องฆ่าเจ้า...เพื่อล้างแค้นเฟนริร์",
  ui_story_5046_50460901_137_dialog_content = "(Fenrir? นั่นคือชื่อพ่อของฉัน! ผู้ชายคนนี้ฆ่าพ่อของฉันเหรอ!?)",
  ui_story_5046_50460901_138_dialog_content = "คุณประเมินความสามารถของคุณสูงเกินไป",
  ui_story_5046_50460901_139_dialog_content = "หอบ...หอบ...",
  ui_story_5046_50460901_140_dialog_content = "แคทเธอรีน แค่มอบจี้แล้วฉันจะไว้ชีวิตเธอ",
  ui_story_5046_50460901_141_dialog_content = "เหนือศพของฉัน...",
  ui_story_5046_50460901_142_dialog_content = "ดื้อแค่ไหน ถ้าเจ้าต้องการตายจริง ข้าจะบังคับเจ้า",
  ui_story_5046_50460901_143_dialog_content = "(แม่!)",
  ui_story_5046_50460901_144_dialog_content = "ฮย้า—!",
  ui_story_5046_50460901_145_dialog_content = "(ไฟไหม้!?แม่เป็นคนเริ่ม?)",
  ui_story_5046_50460901_146_dialog_content = "อ๊าก! ไฟนี้ลุกลามอย่างรวดเร็วได้อย่างไร?",
  ui_story_5046_50460901_147_dialog_content = "นี่เป็นแผนของคุณ แคทเธอรีน?",
  ui_story_5046_50460901_148_dialog_content = "คุณจะไม่ออกไปจากที่นี่ทั้งเป็น...",
  ui_story_5046_50460901_149_dialog_content = "ปล่อยฉันไป! คุณต้องการให้ฉันเผาที่นี่กับคุณ!?",
  ui_story_5046_50460901_150_dialog_content = "ตราบใดที่ฉันล้างแค้น Fenrir...",
  ui_story_5046_50460901_151_dialog_content = "ย้ากกก!",
  ui_story_5046_50460901_152_dialog_content = "(แม่! แม่ยังมองมาที่ฉัน...)",
  ui_story_5046_50460901_153_dialog_content = "...",
  ui_story_5046_50460901_154_dialog_content = "(แม่บอกว่า...อย่าออกมา?)",
  ui_story_5046_50460901_155_dialog_content = "(แม่!? แม่ไม่ขยับ!?)",
  ui_story_5046_50460901_156_dialog_content = "(แม่-!)",
  ui_story_5046_50460901_157_dialog_content = "ฮึ่ม เหงื่อไม่ออกด้วยซ้ำ",
  ui_story_5046_50460901_158_dialog_content = "(ว๊าาาา...แม่...)",
  ui_story_5046_50460901_159_dialog_content = "(ชายคนนั้นกำลังค้นหาบางสิ่งให้แม่...)",
  ui_story_5046_50460901_160_dialog_content = "(ฉันต้องออกไปที่นั่นและฆ่าเขา...เพื่อล้างแค้นให้แม่ของฉัน!)",
  ui_story_5046_50460901_161_dialog_content = "(เปล่า แม่แค่บอกว่าอย่าออกไปไหน...)",
  ui_story_5046_50460901_162_dialog_content = "อากาศมันร้อนนี่...เธอเอาของนั้นไปซ่อนไว้ที่ไหน!?",
  ui_story_5046_50460901_163_dialog_content = "...",
  ui_story_5046_50460901_164_dialog_content = "ในที่สุดก็พบมัน ใบหน้าของฉันแสบร้อนไหม?",
  ui_story_5046_50460901_165_dialog_content = "ไฟ! ไฟ!",
  ui_story_5046_50460901_166_dialog_content = "ฉันไม่สามารถให้ใครเห็นฉันได้",
  ui_story_5046_50460901_167_dialog_content = "(เขาไปแล้ว...แม่ไม่ไปแล้ว...)",
  ui_story_5046_50460901_168_dialog_content = "(แม่...)",
  ui_story_5046_50460901_169_dialog_content = "ไฟนั้นอยู่เหนือการควบคุม แต่ในที่สุดเราก็สามารถดับมันได้...",
  ui_story_5046_50460901_170_dialog_content = "พวกเขาพบแคทเธอรีน แต่เธอหยุดหายใจไปแล้ว...",
  ui_story_5046_50460901_171_dialog_content = "ไฟแบบนั้นจะรัดคุณตาย แม้ว่าไฟจะไม่เคยสัมผัสคุณก็ตาม...",
  ui_story_5046_50460901_172_dialog_content = "ถ้าคุณไม่มีอะไรจะพูดดีๆ ก็แค่ไม่ต้องพูดอะไร",
  ui_story_5046_50460901_173_dialog_content = "ฮึ่ม",
  ui_story_5046_50460901_174_dialog_content = "ช่วยทำความสะอาดสถานที่นี้หากคุณไม่มีอะไรทำ",
  ui_story_5046_50460901_175_dialog_content = "รู้แล้วน่า รู้แล้ว",
  ui_story_5046_50460901_176_dialog_content = "ไปที่นี่! มีเด็กอยู่ในเตาผิง!",
  ui_story_5046_50460901_177_dialog_content = "ฉันไม่เคยได้ยินแคทเธอรีนพูดถึงว่าเธอมีลูก...",
  ui_story_5046_50460901_178_dialog_content = "และเด็กก็ไม่ได้รับบาดเจ็บแม้แต่น้อย แม้ว่าไฟจะโหมกระหน่ำก็ตาม...",
  ui_story_5046_50460901_179_dialog_content = "เฮ้อ... เธอปิดหน้าต่างและจุดเทียนในห้องตอนกลางวัน",
  ui_story_5046_50460901_180_dialog_content = "มันเป็นเพียงเรื่องของเวลาก่อนที่สิ่งนี้จะเกิดขึ้น ดู?",
  ui_story_5046_50460901_181_dialog_content = "มาเถอะ หยุดเป็นโรคร้ายได้แล้ว คำถามที่สำคัญที่สุดในตอนนี้คือ เราจะทำอย่างไรกับเด็กคนนี้",
  ui_story_5046_50460901_182_dialog_content = "พาเธอไปสถานเลี้ยงเด็กกำพร้า?",
  ui_story_5046_50460901_183_dialog_content = "ฉันเดาว่านั่นคือทั้งหมดที่เราสามารถทำได้",
  ui_story_5046_50460901_184_dialog_content = "ฉันมีคำถามอื่นๆ",
  ui_story_5046_50461001_1_dialog_content = "เธอดูเหมือนจะสงบลง",
  ui_story_5046_50461001_2_dialog_content = "ขอบคุณคริสเตน",
  ui_story_5046_50461001_3_dialog_content = "เธอจะขอบคุณฉันไปทำไม?",
  ui_story_5046_50461001_4_dialog_content = "ขอบใจที่เธอรอให้ฮาติฟื้นความทรงจำ",
  ui_story_5046_50461001_5_dialog_content = "คุณไม่คิดว่า Hati เป็นผู้ร้ายด้วยใช่ไหม",
  ui_story_5046_50461001_6_dialog_content = "หลังจากทำการสอบสวนอย่างละเอียด ฉันก็สงสัย Hati น้อยลงอย่างแน่นอน",
  ui_story_5046_50461001_7_dialog_content = "แม้ว่าคดีเหล่านี้ล้วนเกี่ยวข้องกับฮาติ และเบาะแสทุกอย่างก็ชี้ไปที่เธอ",
  ui_story_5046_50461001_8_dialog_content = "แต่ยังมีความขัดแย้งมากมายที่ยังไม่ได้รับการแก้ไข",
  ui_story_5046_50461001_9_dialog_content = "คุณทุ่มเทเต็มที่กับคดีนี้จริงๆ คริสเตน",
  ui_story_5046_50461001_10_dialog_content = "คุณซีนาสสอนฉันว่าเราควรพิจารณาทุกกรณีอย่างจริงจังและอย่าทิ้งเงื่อนงำใด ๆ ไว้เบื้องหลัง",
  ui_story_5046_50461001_11_dialog_content = "แต่เขาก็ยังไม่ยอมให้ผมรับคดีนี้...",
  ui_story_5046_50461001_12_dialog_content = "คริสเตน คุณสืบสวนคดีนี้อย่างลับๆ เหรอ?",
  ui_story_5046_50461001_13_dialog_content = "ใช่แล้ว...",
  ui_story_5046_50461001_14_dialog_content = "เมื่อพูดถึงเรื่องนี้ PlayerNameทำไมคุณถึงหนีไปกับ Hati? เธอกำลังขัดขวางคุณจากความประสงค์ของคุณ",
  ui_story_5046_50461001_15_dialog_content = "ฉันเชื่อว่าเธอไร้เดียงสา และทุกๆ อย่างที่เกิดขึ้น อารมณ์ของเธอก็ไม่คงที่เอาซะเลย",
  ui_story_5046_50461001_16_dialog_content = "เธอต้องการความช่วยเหลือจากฉัน ฉันจึงขอให้เธอพาฉันไปด้วย",
  ui_story_5046_50461001_17_dialog_content = "คุณได้สร้างสายใยแห่งความไว้เนื้อเชื่อใจต่อกันในเวลาอันสั้น...?",
  ui_story_5046_50461001_18_dialog_content = "<size=30>ถ้านายซีนาสไว้ใจฉันได้ขนาดนี้...</size>",
  ui_story_5046_50461001_19_dialog_content = "คุณพบสถานที่นี้ได้อย่างไร",
  ui_story_5046_50461001_20_dialog_content = "ท้องถิ่นแสดงให้ฉันเห็น",
  ui_story_5046_50461001_21_dialog_content = "ไม่ไกลจากสถานเลี้ยงเด็กกำพร้า แต่ก็ยังเป็นส่วนหนึ่งของ Umbraton หลายปีก่อนชาวบ้านที่นี่ใช้ชีวิตอย่างยากลำบาก",
  ui_story_5046_50461001_22_dialog_content = "ปีแห่งไฟสถานเลี้ยงเด็กกำพร้า Istvan ชนะใจผู้คนมากมายหลังจากที่เขารับปากว่าจะแก้ไขสถานการณ์",
  ui_story_5046_50461001_23_dialog_content = "หลังจากได้เป็น Shadowlord แล้ว Istvan ขอให้ผู้คนที่นี่ย้ายไปที่ Umbraton",
  ui_story_5046_50461001_24_dialog_content = "แท้จริงแล้วคือชายคนเดียวกับที่ส่งฮาติไปที่สถานเลี้ยงเด็กกำพร้า ซึ่งพาฉันมาที่นี่",
  ui_story_5046_50461001_25_dialog_content = "เขาบอกว่าก่อนหน้านี้เกิดไฟไหม้ในเมืองนี้ และพบฮาติอยู่ในซากปรักหักพังหลังจากดับไฟแล้ว",
  ui_story_5046_50461001_26_dialog_content = "ผู้หญิงที่อาศัยอยู่ที่นี่เสียชีวิต",
  ui_story_5046_50461001_27_dialog_content = "แต่คนในท้องถิ่นไม่เคยได้ยินผู้หญิงพูดว่าเธอมีลูก ดังนั้นพวกเขาจึงไม่รู้ว่าจะทำอย่างไร",
  ui_story_5046_50461001_28_dialog_content = "ในที่สุดพวกเขาก็ตัดสินใจส่งเด็กไปที่สถานเลี้ยงเด็กกำพร้า เด็กคนนั้นคือฮาติ",
  ui_story_5046_50461001_29_dialog_content = "แค่นี้ใช่ไหม...",
  ui_story_5046_50461001_30_dialog_content = "การทำงานที่น่าทึ่ง คริสเตน คุณค้นพบมากมายด้วยเงื่อนงำเพียงไม่กี่ข้อที่ต้องทำต่อไป",
  ui_story_5046_50461001_31_dialog_content = "อะแฮ่ม! ไม่สำคัญหรอกว่าคุณจะยกย่องฉันมากแค่ไหน ฉันจะพาคุณกลับมาด้วยเพื่อให้ความร่วมมือในการสืบสวน",
  ui_story_5046_50461001_32_dialog_content = "ฉันเชื่อจากก้นบึ้งของหัวใจว่าคุณน่าทึ่งจริงๆ! ฉันรู้ว่าคุณจะเป็นผู้ตัดสินที่ยอดเยี่ยมในอนาคต!",
  ui_story_5046_50461001_33_dialog_content = "ถ้าเขาคิดเหมือนกัน...",
  ui_story_5046_50461001_34_dialog_content = "นายซีนัส?",
  ui_story_5046_50461001_35_dialog_content = "ใช่... คุณซีนาสได้รับบาดเจ็บจากการใช้ Luminatics เพื่อดับไฟ แต่หลังจากนั้น คุณฮาเมลล์ก็ถูกฆ่าตาย...",
  ui_story_5046_50461001_36_dialog_content = "เขาหมดศรัทธาในตัวฉันแล้ว",
  ui_story_5046_50461001_37_dialog_content = "ฉันคิดว่าคุณทำได้ดีมาก คริสเตน",
  ui_story_5046_50461001_38_dialog_content = "แม้ว่าเราจะมีโอกาสพบกันเพียงไม่กี่ครั้ง แต่ฉันสัมผัสได้ว่าคุณเป็นผู้พิพากษาที่มีมโนธรรม อดทน และใจดี",
  ui_story_5046_50461001_39_dialog_content = "D-อย่าคิดว่าคำพูดหวานแหววของเธอจะทำให้ฉัน...",
  ui_story_5046_50461001_40_dialog_content = "ฉันได้รับการฝึกอบรมอย่างมืออาชีพจาก Lumo Hall of Justice! ความเชื่อในความยุติธรรมของฉันจะไม่ถูกสั่นคลอนโดยคนอย่างคุณ!",
  ui_story_5046_50461001_41_dialog_content = "ฉันแค่พูดในสิ่งที่ฉันอยากจะพูด! ฉันไม่ได้หมายความอย่างอื่นด้วย!",
  ui_story_5046_50461001_42_dialog_content = "ถ้าฮาติทำแบบนั้นจริงๆ ฉันคงทำให้เธอสารภาพไปแล้ว",
  ui_story_5046_50461001_43_dialog_content = "แต่ถ้าเธอไม่ได้ทำอะไร คุณก็จับเธอไม่ได้!",
  ui_story_5046_50461001_44_dialog_content = "R-ใช่! นั่นคือความหมายของความยุติธรรม!",
  ui_story_5046_50461001_45_dialog_content = "คุณควรพยายามเชื่อมั่นในตัวเองและเลิกกังวลว่าคนอื่นจะคิดอย่างไร",
  ui_story_5046_50461001_46_dialog_content = "โดยเฉพาะอย่างยิ่งเมื่อพิจารณาว่าคุณน่าทึ่งแค่ไหน!",
  ui_story_5046_50461001_47_dialog_content = "...",
  ui_story_5046_50461001_48_dialog_content = "มีคนเคยบอกคุณไหมว่าคุณค่อนข้างเก่งในการทำให้ผู้หญิงมีความสุข?",
  ui_story_5046_50461001_49_dialog_content = "ฮะ? ฉันทำให้ผู้หญิงมีความสุข?",
  ui_story_5046_50461001_50_dialog_content = "Vice มักจะเกลียดฉันที่ใช้จ่ายเงินและทำให้เธอกังวลเกี่ยวกับค่าใช้จ่ายของ Colossus ทุกวัน",
  ui_story_5046_50461001_51_dialog_content = "คุณควรจะบอกว่าฉันสร้างปัญหาให้สาวๆ เสมอ",
  ui_story_5046_50461001_52_dialog_content = "<size=45>กราาาาาา—</size>",
  ui_story_5046_50461001_53_dialog_content = "นั่นคือ Eclipsite หรือไม่? ดูเหมือนว่ามีมากกว่าหนึ่ง",
  ui_story_5046_50461001_54_dialog_content = "ที่นี่ถูกทิ้งร้างมานาน คาดว่า Eclipsites จะหลอกหลอนบริเวณนี้เท่านั้น",
  ui_story_5046_50461001_55_dialog_content = "แต่ฮาติยังไม่ตื่น ฉันเกรงว่าการพาเธอออกไปตอนนี้อาจเป็นอันตราย",
  ui_story_5046_50461001_56_dialog_content = "ไม่ต้องกังวล มันเป็นเพียงไม่กี่ Eclipsites ฉันจะตัดสินพวกเขาทันที!",
  ui_story_5046_50461002_1_dialog_content = "ฟู่—",
  ui_story_5046_50461002_2_dialog_content = "ออร่า Eclipsite รอบๆ นี้ก็สลายไปในที่สุด",
