  ui_story_5046_50461102_31_dialog_content = "และคุณ Caelestite คุณจะกลายเป็นผู้สมรู้ร่วมคิดของเธอ!",
  ui_story_5046_50461102_32_dialog_content = "ถึงตอนนั้นจะไม่มีใครเชื่อสิ่งที่คุณพูดแม้แต่คำเดียว",
  ui_story_5046_50461102_33_dialog_content = "คิดว่าจะปกปิดความจริงได้เหรอ!?",
  ui_story_5046_50461102_34_dialog_content = "คุณคิดว่าคุณคนเดียวสามารถใส่ร้ายเราด้วยการโกหกของคุณ!?",
  ui_story_5046_50461102_35_dialog_content = "ความจริง ความเท็จ... สุดท้ายแล้วสำคัญอย่างไร?",
  ui_story_5046_50461102_36_dialog_content = "สิ่งสำคัญคือฉันใช้ชีวิตในฐานะอัศวินต่อไปอย่างปลอดภัยใน Lumopolis โดยไม่มีเหตุการณ์ใดเกิดขึ้นอีก...",
  ui_story_5046_50461102_37_dialog_content = "ส่วนความจริงนั้น...จะถูกฝังอยู่กับกระดูกของเธอ ลึกลงไปในดินตลอดกาล!",
  ui_story_5046_50461102_38_dialog_content = "ท่าน... ท่านพูดอย่างนั้นได้อย่างไร?",
  ui_story_5046_50461102_39_dialog_content = "คุณไม่เคยสอนฉันให้รักษาความยุติธรรมและต่อสู้เพื่อความจริงเหรอ? ทำไม ทำไมถึงพูดแบบนั้น...?",
  ui_story_5046_50461102_40_dialog_content = "คริสเตน เธอถือว่าฉันเป็นคนสำคัญในใจเธอหรือเปล่า?",
  ui_story_5046_50461102_41_dialog_content = "อ๊าา!",
  ui_story_5046_50461102_42_dialog_content = "ในเมื่อผมมีความหมายกับคุณมาก คุณจะไม่ทำทุกวิถีทางเพื่อรักษาชื่อเสียงและตำแหน่งของฉัน แม้ว่ามันจะต้องตายเพื่อฉันก็ตาม",
  ui_story_5046_50461102_43_dialog_content = "เซอร์... เซอร์ คุณกำลังพูดอะไร...?",
  ui_story_5046_50461102_44_dialog_content = "คุณเสี่ยงชีวิตเพื่อช่วย Kristen เมื่อหลายปีก่อน! ใจร้ายถึงขนาดขู่ฆ่าเธอได้ยังไง!",
  ui_story_5046_50461102_45_dialog_content = "(ฮาติ! ฉันกำลังพูดกับคุณโดยใช้พลังจิตของฉัน! เราต้องหาทางช่วยคริสเตนให้ได้!)",
  ui_story_5046_50461102_46_dialog_content = "PlayerName?",
  ui_story_5046_50461102_47_dialog_content = "(ฉันจะเบี่ยงเบนความสนใจของซีนัส คุณหาโอกาสแอบดูเขาสิ!)",
  ui_story_5046_50461102_48_dialog_content = "เข้าใจแล้วครับ",
  ui_story_5046_50461102_49_dialog_content = "ฉันช่วยเธอ? คุณหมายถึงไฟนั่นเหรอ? ฉันคิดว่าเธอเป็นหนี้ฉันมากกว่านี้ซะอีก ตอนนี้เธอมีโอกาสที่จะตอบแทนฉัน",
  ui_story_5046_50461102_50_dialog_content = "เว้นแต่การหักเงินครั้งก่อนของฉันจะผิดพลาด คุณเสี่ยงชีวิตเพื่อเข้าไปในกองไฟและช่วยชีวิตคริสเตน...",
  ui_story_5046_50461102_51_dialog_content = "แล้วคิดจะทำร้ายเธอตอนนี้ได้ยังไง!?",
  ui_story_5046_50461102_52_dialog_content = "ใช่ สาวน้อยที่ฉันสละชีวิตเพื่อรักษาและสอนมาหลายปี...",
  ui_story_5046_50461102_53_dialog_content = "ฉันจะพาตัวเองไปทำร้ายเธอได้อย่างไร?",
  ui_story_5046_50461102_54_dialog_content = "คุณคารอน...",
  ui_story_5046_50461102_55_dialog_content = "แต่คริสเตน สาวน้อยของฉัน...",
  ui_story_5046_50461102_56_dialog_content = "จากจุดเริ่มต้น คุณเป็นเพียงเบี้ยสำหรับฉัน",
  ui_story_5046_50461102_57_dialog_content = "และนั่นรวมถึงไฟด้วย มันเป็นส่วนหนึ่งของแผนของฉันทั้งหมด",
  ui_story_5046_50461102_58_dialog_content = "ว่าไงนะ!?",
  ui_story_5046_50461102_59_dialog_content = "ฉันอยากปีนขึ้นไปบนหลังของขุนนางที่มีอำนาจมานานแล้วและเข้าสู่สังคมลูโมโปลิส คฤหาสน์ของคุณบังเอิญอยู่ใกล้ ๆ",
  ui_story_5046_50461102_60_dialog_content = "ฉันรู้อย่างรวดเร็วว่าทุกคนที่ทำงานในคฤหาสน์ในวันนั้นเป็นนินจาที่อ่อนแอ ดังนั้นฉันจึงติดสินบนความช่วยเหลือและจุดไฟเผาสถานที่นั้น",
  ui_story_5046_50461102_61_dialog_content = "ฉันแสร้งทำเป็นเดินผ่านไปและทำราวกับว่าฉันกำลังเสี่ยงชีวิตและแขนขาอย่างสิ้นหวังเพื่อช่วยเหลือหญิงสาวผู้สูงศักดิ์ผู้น่าสงสารแห่งลูโมโปลิสผู้น่าสงสารคนนี้",
  ui_story_5046_50461102_62_dialog_content = "แน่นอนว่าครอบครัวของเธอรู้สึกขอบคุณฉันมากที่ทำให้ฉันเข้าสู่สังคมลูโมโปลิสได้อย่างราบรื่นและใช้ชีวิตอย่างที่ฉันใฝ่ฝันมาตลอด",
  ui_story_5046_50461102_63_dialog_content = "ทั้งหมดเป็นเพราะคุณ ฉัน... ไม่สิ คริสเตน",
  ui_story_5046_50461102_X63_dialog_content = "ดูสิ ฉันเผาหน้าตัวเองเพื่อช่วยนาย!",
  ui_story_5046_50461102_64_dialog_content = "คุณ... คุณมันน่ารังเกียจ! ฉันจะไม่ไว้ชีวิตคุณ!",
  ui_story_5046_50461102_65_dialog_content = "มันคุ้มไหมที่จะทำให้ตัวเองเสียโฉมเพียงเพื่อยกย่องตัวเองกับขุนนางชั้นสูงของลูโมโปลิส?",
  ui_story_5046_50461102_66_dialog_content = "คุณเคยลิ้มรสพลังไหม คาเลสไทต์?",
  ui_story_5046_50461102_67_dialog_content = "อำนาจสามารถแลกได้ด้วยเงิน แต่เงินไม่จำเป็นต้องซื้ออำนาจเสมอไป",
  ui_story_5046_50461102_68_dialog_content = "ตราบใดที่คุณมีอำนาจ ก็ไม่มีอะไรเกินเอื้อม และไม่มีใครขวางทางคุณได้!",
  ui_story_5046_50461102_69_dialog_content = "ใช่มั้ยคริสเตน?",
  ui_story_5046_50461102_70_dialog_content = "คุณเกิดมาเป็นขุนนางแห่งลูโมโปลิส มันคงเป็นความรู้สึกที่วิเศษใช่มั้ยล่ะ?",
  ui_story_5046_50461102_71_dialog_content = "ความไม่สบายใจอยู่ที่ศีรษะที่สวมมงกุฎ...",
  ui_story_5046_50461102_72_dialog_content = "ขุนนางควรมีลักษณะอันสูงส่ง",
  ui_story_5046_50461102_73_dialog_content = "ผู้ที่ใช้สถานะอันสูงส่งเพื่อประโยชน์ส่วนตนไม่สมควรถูกเรียกว่าขุนนาง",
