  ui_story_5046_50461201_4_dialog_content = "มันเป็นเวลานาน, PlayerName.",
  ui_story_5046_50461201_5_dialog_content = "โอ้ พิตต์แมน!",
  ui_story_5046_50461201_6_dialog_content = "ฮาติอยู่ที่นี่เหรอ? ฉันได้ยินมาว่าเธอมาเยี่ยมยักษ์ใหญ่",
  ui_story_5046_50461201_7_dialog_content = "คริสเตน.",
  ui_story_5046_50461201_8_dialog_content = "เอาล่ะ นี่คือจี้",
  ui_story_5046_50461201_9_dialog_content = "จี้แม่...",
  ui_story_5046_50461201_10_dialog_content = "ขณะนี้ได้มอบเสนาสน์ให้ข้าพเจ้าสอบปากคำเพิ่มเติมแล้ว",
  ui_story_5046_50461201_11_dialog_content = "ต้องขอบคุณคุณ, PlayerNameเรายังพบเงื่อนงำเพิ่มเติมที่สำคัญ <color=#FFB400>อีกกรณีหนึ่ง</color>.",
  ui_story_5046_50461201_12_dialog_content = "ฮ่าฮ่า... ฉันดีใจที่ช่วยได้",
  ui_story_5046_50461201_13_dialog_content = "ใครจะคิดว่าฉันถูกลักพาตัวจะทำให้เกิดดราม่ามากมายขนาดนี้?",
  ui_story_5046_50461201_14_dialog_content = "อะแฮ่ม...",
  ui_story_5046_50461201_15_dialog_content = "โอ้ใช่. ฉันมีคำถามสองสามข้อที่จะถาม...",
  ui_story_5046_50461201_16_option_content = "ใครคือผู้ร้ายตัวจริงในคดีลอบวางเพลิงในช่วงสองเดือนที่ผ่านมา?",
  ui_story_5046_50461201_17_dialog_content = "การสืบสวนของเราแสดงให้เห็นว่าคดีลอบวางเพลิงใน Umbraton ในช่วงสองเดือนที่ผ่านมาล้วนใช้เชื้อเพลิงเดียวกัน รวมทั้งการซ้อมที่สถานเลี้ยงเด็กกำพร้าด้วย",
  ui_story_5046_50461201_18_dialog_content = "ฉันส่งคนไปตรวจสอบเชื้อเพลิงนี้ และดูเหมือนว่ามีเพียงไม่กี่ร้านเท่านั้นที่ขายน้ำมันนี้",
  ui_story_5046_50461201_19_dialog_content = "เจ้าของร้านระบุว่า Zenas ซื้อเชื้อเพลิงจำนวนมากเมื่อสองเดือนก่อน",
  ui_story_5046_50461201_20_dialog_content = "เซนาสยังยอมรับด้วยว่าเขาเริ่มจุดไฟทั้งหมดนี้ด้วยความตั้งใจที่จะปิดปากผู้ที่ตกเป็นเหยื่อ",
  ui_story_5046_50461201_21_dialog_content = "แต่ทำไมเขาถึงฆ่าคนเหล่านั้น?",
  ui_story_5046_50461201_22_dialog_content = "มันเกี่ยวข้องกับ <color=#FFB400>กรณีนั้น</color>.",
  ui_story_5046_50461201_23_dialog_content = "ในเวลานั้น พนักงานห้าคนรวมถึง Hamell ใช้สถานเลี้ยงเด็กกำพร้าเป็นที่กำบังในการส่งเด็กไปทดลอง",
  ui_story_5046_50461201_24_dialog_content = "ยกเว้นซีนาสและฮาเมล เด็กกำพร้าอีกสามคนที่รอดชีวิตจากเหตุไฟไหม้ที่สถานเลี้ยงเด็กกำพร้าไม่ได้ดีนัก",
  ui_story_5046_50461201_25_dialog_content = "ดังนั้นพวกเขาทั้งสามคนจึงใช้อดีตร่วมกันเพื่อแบล็กเมล์ซีนาส และซีนาสก็ถูกบีบให้ต้องจ่ายสำหรับการปิดปากเงียบของพวกเขา",
  ui_story_5046_50461201_26_dialog_content = "แต่เรียกร้องมากขึ้นเรื่อยๆ...",
  ui_story_5046_50461201_27_dialog_content = "แล้วซีนัสก็สั่งปิดปากพวกเขาเป็นการถาวร",
  ui_story_5046_50461201_28_dialog_content = "ถูกต้อง",
  ui_story_5046_50461201_29_dialog_content = "ใครเป็นคนฆ่านายฮาเมล?",
  ui_story_5046_50461201_30_dialog_content = "เซนัสยอมรับว่าเป็นผู้จุดไฟและสังหารอดีตพนักงานสถานเลี้ยงเด็กกำพร้าทั้งสามคน",
  ui_story_5046_50461201_31_dialog_content = "มีคนห้าคนที่ทำงานในสถานเลี้ยงเด็กกำพร้าที่เกี่ยวข้องในคดีนี้ รวมทั้งซีนัสด้วย",
  ui_story_5046_50461201_32_dialog_content = "แล้วซีนาสฆ่าคุณฮาเมลล์เหรอ?",
  ui_story_5046_50461201_33_dialog_content = "เป็นเรื่องที่น่าสงสัยอย่างมาก แต่ขณะนี้ยังไม่มีหลักฐาน และเขายังไม่ยอมรับ",
  ui_story_5046_50461201_34_dialog_content = "เขามีส่วนรับผิดชอบต่อการฆาตกรรมมากมายขนาดนี้จริงหรือ...?",
  ui_story_5046_50461201_35_dialog_content = "(คริสเตนดูไม่เหมือนว่าเธอทำได้ดี...)",
  ui_story_5046_50461201_36_dialog_content = "คริสเตน คุณสบายดีไหม",
  ui_story_5046_50461201_37_dialog_content = "คุณเห็นฉันอ่อนแอจริงๆเหรอ PlayerName?",
  ui_story_5046_50461201_38_dialog_content = "N-ไม่ นั่นไม่ใช่สิ่งที่ฉันหมายถึง! ฉันเพียงแค่...",
  ui_story_5046_50461201_39_dialog_content = "ไม่เป็นไร",
  ui_story_5046_50461201_40_dialog_content = "ฉันจำทุกสิ่งที่คุณพูดกับฉันในวันนั้น PlayerName.",
  ui_story_5046_50461201_41_dialog_content = "PlayerName บอกฉันว่าฉันจะเป็นผู้พิพากษาที่ยอดเยี่ยมในอนาคต",
  ui_story_5046_50461201_42_dialog_content = "ด้วยผู้คนมากมายที่อยู่รอบตัวฉัน ให้กำลังใจและสนับสนุนฉันตลอดเวลา ไม่มีทางที่ฉันจะรู้สึกเศร้าที่ต้องอยู่คนเดียว",
  ui_story_5046_50461201_43_dialog_content = "แม้ว่าฉันยังมีหนทางอีกยาวไกลก่อนจะไปถึงเป้าหมาย แต่ฉันจะพยายามอย่างเต็มที่เพื่อก้าวต่อไป",
  ui_story_5046_50461201_44_dialog_content = "เพราะฉันยอดเยี่ยมจริงๆ! ไม่ใช่ฉันเหรอ PlayerName?",
  ui_story_5046_50461201_45_dialog_content = "นี่เรากำลังพูดถึงคริสเตนใช่ไหม? แน่นอนคุณเป็น!",
  ui_story_5046_50461201_46_dialog_content = "จริงด้วยสินะ",
  ui_story_5046_50461201_47_dialog_content = "ฉันที่สองที่",
  ui_story_5046_50461201_48_dialog_content = "โอ้! ฉันลืมไปว่ามิสเตอร์พิตต์แมนยังอยู่ที่นี่...",
  ui_story_5046_50461201_49_dialog_content = "อะแฮ่ม... ฉันให้จี้ Hati แก่เธอแล้ว ถ้าเธอไม่มีอะไรจะคุยกับฉัน ก็ปล่อยฉันไปเถอะ",
  ui_story_5046_50461201_50_dialog_content = "ลาก่อน",
  ui_story_5046_50461201_51_dialog_content = "...",
  ui_story_5046_50461201_52_dialog_content = "รู้สึกประหม่าไหม ฮาติ?",
  ui_story_5046_50461201_53_dialog_content = "ช่าย",
  ui_story_5046_50461201_54_dialog_content = "จี้ทั้งสองนี้เป็นคู่ แม่ให้ฉันครึ่งหนึ่งในตอนนั้น",
  ui_story_5046_50461201_55_dialog_content = "แม่บอกว่าตราบใดที่เอาสองซีกนี้มารวมกัน ครอบครัวเราจะอยู่ด้วยกันตลอดไป...",
  ui_story_5046_50461201_56_dialog_content = "แต่แม่กับผมห่างกันไปนาน... บู้ฮู้...",
