  ui_story_5046_50461201_60_dialog_content = "(ให้แม่ร้องกล่อมนอน...)",
  ui_story_5046_50461201_61_dialog_content = "(ลาลาลา ♪ ลาลาลา ♪)",
  ui_story_5046_50461201_62_dialog_content = "(ฮาติ เฝ้าดูเธอหลับสนิท ฉันหวังว่าช่วงเวลานี้จะคงอยู่ตลอดไป)",
  ui_story_5046_50461201_63_dialog_content = "(แต่ฉันก็อยากเห็นคุณโตขึ้น ฉันเดาว่าสุดท้ายแล้วคุณจะดูเหมือน Fenrir มากขึ้นเรื่อยๆ)",
  ui_story_5046_50461201_64_dialog_content = "(ตอนเกิดคุณเป็นแค่ลูกบอลขนปุย แต่ตอนนี้คุณสูงเกือบถึงเข่าผมแล้ว)",
  ui_story_5046_50461201_65_dialog_content = "(ถึงตอนนี้คุณอาจจะแก่แล้ว แต่คุณก็ยังชอบให้ฉันอุ้มคุณในอ้อมแขนและพาคุณเข้านอน และเมื่อคุณตื่นขึ้น คุณก็ยังขอให้ฉันอุ้มคุณไปที่โต๊ะเพื่อทานอาหารเย็น...)",
  ui_story_5046_50461201_66_dialog_content = "(ตอนนี้ฉันแทบจะยกเธอไม่ไหวแล้ว นับประสาอะไรที่จะเดินไปกับเธอ!)",
  ui_story_5046_50461201_67_dialog_content = "(พอแก่แล้วเดินไม่ได้ก็จะหามขึ้นนอนแล้ววางบนแคร่...)",
  ui_story_5046_50461201_68_dialog_content = "(ฮาติ... มีอะไรอยากจะบอกเธอมากมาย...)",
  ui_story_5046_50461201_69_dialog_content = "(ฉันหวังว่าฉันจะสามารถเฝ้าดูคุณและเติบโตไปกับคุณเสมอ...)",
  ui_story_5046_50461201_70_dialog_content = "(...)",
  ui_story_5046_50461201_71_dialog_content = "(...)",
  ui_story_5046_50461201_72_dialog_content = "(...)",
  ui_story_5046_50461201_73_dialog_content = "...",
  ui_story_5046_50461201_74_dialog_content = "ฉันไม่กลัวคุณอีกต่อไป และฉันจะไม่กลัว... พลังนี้ด้วย",
  ui_story_5046_50461201_75_dialog_content = "ตอนนี้ฉันยอมรับตัวเองได้อย่างสมบูรณ์แล้ว",
  ui_story_5046_50461201_76_dialog_content = "ไม่ว่าจะเป็นพวกฮาติที่เคยเกรงกลัวอำนาจของเธอและเกลียดตัวเอง",
  ui_story_5046_50461201_77_dialog_content = "หรือฮาติที่ใช้เปลวเพลิงของเธอเพื่อปกป้องคนสำคัญสำหรับเธอ",
  ui_story_5046_50461201_78_dialog_content = "ไม่ว่าจะเป็นฮาติคนไหนก็ล้วนแต่เป็นฉัน",
  ui_story_5046_50461201_79_dialog_content = "(ฉัน...พร้อมยอมรับตัวเองหรือยัง...?)",
  ui_story_5046_50461201_80_dialog_content = "ฉันพร้อม",
  ui_story_5046_50461202_1_dialog_content = "ฉันชนะ?",
  ui_story_5046_50461202_2_dialog_content = "คุณคือ...?",
  ui_story_5046_50461202_3_dialog_content = "(ตอนนี้คุณยอมรับตัวเองได้ทั้งหมดแล้ว)",
