  ui_story_5046_50461202_31_dialog_content = "<color=#e8d9bb>คลิก—</color>",
  ui_story_5046_50461202_32_dialog_content = "ดูเหมือนว่ามีบางอย่างโผล่ออกมาที่ด้านล่างหลังจากประกอบทั้งสองส่วนเข้าด้วยกัน...",
