  ui_story_5046_50461202_34_dialog_content = "ท-นี่คือ...",
  ui_story_5046_50461202_35_dialog_content = "รูปเยอะมาก...",
  ui_story_5046_50461202_36_dialog_content = "นี่คือ...ภาพครอบครัวของฉันที่ฉันวาดเมื่อยังเล็ก",
