  ui_story_5046_50461202_46_dialog_content = "แต่ดูรูปนี้แล้วคิดว่าต้องเป็นเขาแน่ๆ...",
  ui_story_5046_50461202_47_dialog_content = "\"ตราบใดที่คุณรวมสองส่วนนี้เข้าด้วยกัน ครอบครัวของเราก็จะอยู่ด้วยกันตลอดไป...\"",
  ui_story_5046_50461202_48_dialog_content = "ตอนนี้ครอบครัวของเราจะอยู่ด้วยกันตลอดไป",
  ui_story_5046_50461202_49_dialog_content = "<color=#e8d9bb>มุมหนึ่งในอัมบราตัน</color>",
  ui_story_5046_50461202_50_dialog_content = "หลังจากมอบจดหมายให้เซนาสแล้ว ข้าพเจ้าก็ตามเขาไป",
  ui_story_5046_50461202_51_dialog_content = "พวกคุณเกาะติดและหวีทุกตารางนิ้ว",
  ui_story_5046_50461202_52_dialog_content = "ครับ!",
  ui_story_5046_50461202_53_dialog_content = "...",
  ui_story_5046_50461202_54_dialog_content = "(ทำไมเขาไปทางนี้...? เขากำลังไปสถานเลี้ยงเด็กกำพร้า?)",
  ui_story_5046_50461202_55_dialog_content = "หายไปนานนะเพื่อนเก่า",
  ui_story_5046_50461202_56_dialog_content = "นายนี่เอง",
  ui_story_5046_50461202_57_dialog_content = "(ฮาเมลล์? สิ่งนั้นในมือของเขาอาจเป็นสิ่งที่ Shadowlord ต้องการ?)",
  ui_story_5046_50461202_58_dialog_content = "ไม่พอใจที่เจอเพื่อนเก่าของคุณ?",
  ui_story_5046_50461202_59_dialog_content = "ฉันแค่กลัวว่าคุณไม่ได้มาที่นี่เพราะต้องการพบฉัน แต่เพราะคุณต้องการบางอย่างจากฉัน",
  ui_story_5046_50461202_60_dialog_content = "อย่าดูถูกเหยียดหยาม ครั้งนี้ฉันมาที่นี่เพื่อแจ้งข่าวให้คุณทราบ",
  ui_story_5046_50461202_61_dialog_content = "เธอจึงขอพบ เกี่ยวอะไรกับผม?",
  ui_story_5046_50461202_62_dialog_content = "อังเดรและอีกสองคนตายแล้ว ไม่ช้าก็เร็วก็จะถึงคราวของเรา",
  ui_story_5046_50461202_63_dialog_content = "แทนที่จะรอให้เธอมาที่ประตูของเรา ออกไปทักทายเธอกันเถอะ",
  ui_story_5046_50461202_64_dialog_content = "(รู้สึกเหมือนว่า Hamell มองไปที่นั่นโดยไม่รู้ตัว)",
  ui_story_5046_50461202_65_dialog_content = "ฉันรู้ว่าคุณต้องการถามว่าทำไมฉันไม่ทำอะไร",
  ui_story_5046_50461202_66_dialog_content = "ในจดหมายของเธอ เธอเรียกชื่อฉัน ถ้ามีใครรู้ความเชื่อมโยงระหว่างเรา มันอาจจะซับซ้อนกว่านี้มาก",
  ui_story_5046_50461202_67_dialog_content = "ถ้าอย่างนั้น ฉันคงไม่สามารถปกป้องคุณได้อีกต่อไป ใครจะว่า... คุณอาจจะโดนหาเรื่องด้วยซ้ำ",
  ui_story_5046_50461202_68_dialog_content = "คุณกำลังขู่ฉัน...",
  ui_story_5046_50461202_69_dialog_content = "เราทุกคนต้องดูแลตัวเอง นี่คือที่อยู่",
  ui_story_5046_50461202_70_dialog_content = "ได้เลย ฉันช่วยคุณได้ แต่คุณต้องหาคนมาช่วยฉัน",
  ui_story_5046_50461202_71_dialog_content = "หลังจากซีนัสจากไป ฉันค้นหารอบๆ ขณะที่ฮาเมลหลับอยู่และพบมัน",
  ui_story_5046_50461202_72_dialog_content = "บันทึกวันที่ทำธุรกรรม ราคา และข้อมูลผู้ซื้อ",
  ui_story_5046_50461202_73_dialog_content = "สุดยอดเลย",
  ui_story_5046_50461202_74_dialog_content = "หลายปีก่อน Umbraton เป็นดินแดนที่วุ่นวายและไร้กฎหมาย ชาวลูโมโปลิสถือว่าที่นี่เป็นที่ทิ้งขยะที่พวกเขาฝังบาป",
  ui_story_5046_50461202_75_dialog_content = "ตอนนี้ฉันเป็นผู้พิทักษ์ของ Umbraton ฉันจะไม่ปล่อยให้มันกลับไปเป็นเหมือนเดิม",
