  ui_story_5046_50461202_84_dialog_content = "ฉันมักจะติดตามคุณอย่างสุ่มสี่สุ่มห้า ก้าวหน้าไปในทิศทางที่คุณต้องการให้ฉันไปทั้งในความคิดและการกระทำของฉัน",
