  ui_story_5046_50461202_109_dialog_content = "<color=#e8d9bb>พิธีวันเสร็จสถานเลี้ยงเด็กกำพร้า Umbraton</color>",
  ui_story_5046_50461202_110_dialog_content = "ความสมบูรณ์ของสถานเลี้ยงเด็กกำพร้าแห่งนี้เป็นสัญลักษณ์ของความพยายามอย่างอุตสาหะของพลเมือง Umbraton ที่ห่วงใยนับไม่ถ้วน โปรดให้ฉันใช้โอกาสนี้แสดงความขอบคุณต่อผู้คนเหล่านี้อีกครั้ง!",
  ui_story_5046_50461202_111_dialog_content = "ฉันขอประกาศให้สถานเลี้ยงเด็กกำพร้า Umbraton เสร็จสมบูรณ์อย่างเป็นทางการ!",
