  ui_story_5046_50461202_115_dialog_content = "สถานเลี้ยงเด็กกำพร้านี้อยู่ภายใต้การดูแลของ Shadowlord ของ Umbraton ดังนั้นคุณไม่ต้องกังวลเกี่ยวกับเรื่องนี้ PlayerName.",
